INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (1, NULL, '土壤呈強酸性', '根生長不良、生長延遲。', '施用石灰或草木灰中和酸性，增加土壤 pH 值。', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-dis-1');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (2, NULL, '土壤通氣不良', '根部腐爛。', '中耕鬆土，或在介質中加入珍珠石、增加孔隙。', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-dis-2');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (3, NULL, '土壤排水不良', '常因底層有硬土層造成生長延遲。', '改善排水系統，打破深層硬土，或更換疏水性好的介質。', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-dis-3');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (4, NULL, '土壤過份乾燥', '葉尖捲曲褐化，出現斑點或斑塊，全株黃化、落葉、萎凋或大量落葉。', '建立規律澆水制度，可覆蓋稻草減少水分蒸發。', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-dis-4');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (5, NULL, '土壤酸鹼值不平衡', '嫩葉退綠造成葉片呈黃綠狀。', '檢測土壤 pH 值，根據結果調整（酸則加鹼，鹼則加酸）。', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-dis-5');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (6, NULL, '土壤鹽基(EC)過高', '葉尖捲曲褐化，落葉、萎凋或大量落葉。', '以大量清水淋洗土壤排除鹽分，並暫停施肥。', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-dis-6');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (7, NULL, '土壤條件環境劇變', '根系發育不良、植株衰弱。', '設置遮陽網或溫室控溫，避免環境因子短時間內大幅震盪。', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-dis-7');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (8, NULL, '微量元素不平衡', '嫩葉退綠造成葉片呈黃綠狀。', '噴施綜合微量元素葉面肥，快速補充缺失養分。', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-dis-8');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (9, NULL, '肥料中之鹽分累積', '土壤表層有結晶體、堅硬。', '移除表土結晶，充分灌水洗鹽，減少化學肥料使用。', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-dis-9');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (10, NULL, '氮肥過多', '頂端葉片繁茂但開花少。', '減少氮肥，增施磷鉀肥，促進花芽分化。', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-dis-10');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (11, NULL, '肥料傷害(肥料過多)', '葉尖褐化或出現塊斑、葉片黃化，嚴重者葉片乾縮、落葉，甚至全株萎凋。', '立即大量澆水稀釋肥料濃度，嚴重時需更換部分土壤。', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-dis-11');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (12, NULL, '肥料不足', '葉片黃化、生長延遲、葉片減少及植株短小。', '定期定量施用平衡型肥料 (N-P-K 比例均衡)。', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-dis-12');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (13, NULL, '肥料不足且氮肥嚴重不足', '植株矮化、新葉變小、老葉黃化。', '追施速效性氮肥（如尿素），並注意土壤有機質補充。', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-dis-13');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (14, NULL, '缺鉀', '葉片由老葉葉緣向內黃化。', '施用硫酸鉀或硝酸鉀肥料，增強植株抗性。', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-dis-14');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (15, NULL, '缺鎂', '老葉葉脈間黃化，新葉黃化但葉脈仍為綠色。', '施用苦土石灰（含有碳酸鎂）或噴灑硫酸鎂溶液。', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-dis-15');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (16, NULL, '水分不足', '葉片黃化、頂端葉片褐化、植株萎凋。', '立即補水，並確保水分滲透至根系所在深度。', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-dis-16');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (17, NULL, '水分過多', '老葉黃化，葉間捲曲褐化，葉尖褐化或由葉尖開始出現黃色、褐色斑點，葉片減少，嚴重者落葉；生長不良、生長延遲、植株褪色，嚴重者莖部腐爛、植株萎凋。', '停止澆水，加強通風，若已腐爛需剪除爛根並換盆消毒。', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-dis-17');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (18, NULL, '濕度太低', '頂端葉片褐化、葉片乾縮。', '在植株周圍噴霧增加空氣濕度，或使用加濕器。', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-dis-18');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (19, NULL, '乾旱', '葉片黃化，葉片出現黃色、褐色斑點。', '穩定灌溉，並考慮在土表鋪設覆蓋物保持濕潤。', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-dis-19');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (20, NULL, '冬季光照不足', '生長延遲。', '移動植株至向陽處，或使用人工植物燈補光。', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-dis-20');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (21, NULL, '白粉病', '葉面出現白色粉狀斑點，為白粉病感染。', '改善通風、移除病葉，可噴灑硫磺或苦楝油防治。', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-dis-21');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (24, 2, '葉斑病', '葉面出現散佈的黑斑點，疑似葉斑病初步感染。', '移除受感染葉片。保持良好通風，避免葉面長時間潮濕。必要時可考慮使用有機殺菌劑。', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-dis-24');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (25, 535, '腐爛', '水果因真菌或細菌感染，導致嚴重腐爛、脫水和萎縮。', '將腐爛水果移除並妥善丟棄，避免病原體擴散傳染其他健康果實。', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-dis-25');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (26, 563, '痂病', '果實表面出現不規則黑褐色痂狀斑點，影響外觀。', '及時清除病果病葉，保持果園通風良好，必要時可噴灑適當殺菌劑進行防治。', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-dis-26');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (27, 386, '發芽', '馬鈴薯已發芽產生茄鹼，食用有毒害。', '建議丟棄已發芽馬鈴薯。儲存於陰涼避光處可延緩發芽。', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-dis-27');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (28, 632, '畸形果', '草莓果實發育異常變形。', '可能因授粉或環境引起，需改善條件。', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-dis-28');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (29, 639, '早疫病 (Early Blight)', '主要危害葉片、莖和果實。葉片上出現暗褐色同心輪紋的圓形病斑，周圍有黃色暈環。老葉先發病，嚴重時葉片乾枯脫落。', '發病初期可噴灑 75% 百菌清可濕性粉劑 600 倍液，或 50% 撲滅寧可濕性粉劑 1500 倍液。注意田間通風，雨後及時排水，並移除病殘體。', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-dis-29');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (30, 639, '晚疫病 (Late Blight)', '危害葉、莖、果。葉片上出現水浸狀暗綠色大斑，濕度高時葉背病斑邊緣長出白色黴層。果實上則形成暗褐色不規則的雲紋狀硬塊。', '發病初期噴灑 64% 殺毒礬可濕性粉劑 500 倍液，或 72% 克露可濕性粉劑 800 倍液。避免在低溫高濕環境下澆水，保持葉面乾燥。', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-dis-30');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (31, 639, '灰黴病 (Gray Mold)', '主要危害果實和花器。果實上病斑呈水浸狀，後期長出大量灰色黴層。花、葉、莖部受害後也會軟腐並產生灰色黴層。', '發病初期噴灑 50% 速克靈可濕性粉劑 2000 倍液，或 40% 嘧黴胺懸浮劑 1000 倍液。增加通風，降低濕度，及時摘除病花、病果。', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-dis-31');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (32, 639, '病毒病 (Virus Disease)', '葉片出現黃綠相間的斑駁、畸形、捲曲、變小。植株矮化，生長緩慢，嚴重影響開花結果。', '病毒病無特效藥，重在預防。主要透過防治蚜蟲、粉蝨等傳播媒介來控制。發病初期可噴灑病毒A、菌毒清等藥劑緩解，並拔除病株。', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-dis-32');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (33, 639, '臍腐病 (Blossom-End Rot)', '非傳染性生理病害。果實底部（臍部）出現水浸狀暗褐色或黑色凹陷的乾腐斑，是因缺鈣或水分供應不均引起。', '保持土壤水分均勻供給，避免忽乾忽濕。葉面噴施 0.3%~0.5% 的氯化鈣或硝酸鈣溶液，每週一次，連續 2-3 次。', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-dis-33');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (34, 834, '乾旱', '土地嚴重乾旱龜裂，植物面臨缺水壓力。', '立即提供足夠灌溉，改善土壤濕度，幫助植物恢復生長。', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-dis-34');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (35, 689, '褐根病', '症狀：全株枯萎；確認方式：現地診察。', '此官方歷史案例含特定藥劑、濃度或施用方式，可能不符合目前核准用法，系統不直接回傳該舊處方。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-9763c15a8399f1d1c23c10f7');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (36, 847, '褐根病', '症狀：根部已有菌絲面產生；確認方式：現地診察。', '官方歷史案例建議：為避免容易造成公共危險，建議連根移除立地進行土壤燻蒸消毒。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-db68257be2e53120a60d0040');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (37, 849, '葉震病', '症狀：起初在針葉上形成許多黃色或黃褐色的小斑點，而後在病葉上形成一節節黃褐色至褐色的病斑，並有濃褐色之帶狀線，以後葉片逐漸變褐色至灰褐色枯死；確認方式：現地診察。', '官方歷史案例建議：現場勘查發現周圍地上有掉落枯萎葉子及松樹本上葉片上均有病原菌之子囊果，建議立即清除，疫區建議噴施波爾多劑。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-549003517f12ee596223bd5d');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (38, 691, '炭疽病', '症狀：被害梢部及葉變褐色枯死，後期轉為灰褐色，在枯死枝條上生出許多粉紅色球形或半圓球形之小點，，導致黑褐色壞疽，嚴重時枝枯或地上部枯死；確認方式：現地診察。', '官方歷史案例建議：現場勘查發現炭疽病危害防治上請參考植物保護手冊果樹炭疽病用藥。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-2d706bb57d87f2033f5a5102');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (39, 718, '側柏枝枯病', '症狀：枯死；確認方式：樣本檢驗。', '官方歷史案例建議：為側柏枝枯病防治請參考所附資料 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-80c44b637909ea168194cfb6');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (40, 718, '枝枯病', '症狀：枝條葉片枯萎黃化；確認方式：現地診察。', '此官方歷史案例含特定藥劑、濃度或施用方式，可能不符合目前核准用法，系統不直接回傳該舊處方。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-2ba2a488a5761c163c3eba61');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (41, 851, '煤煙病', '症狀：葉部黑色物覆說A苗木生長不良。；確認方式：樣本檢驗。', '此官方歷史案例含特定藥劑、濃度或施用方式，可能不符合目前核准用法，系統不直接回傳該舊處方。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-ffdc425769aaa049298e2959');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (42, 852, '褐根病', '症狀：本案為日據時代種種之光腊樹,其幹下有蟻窩,葉子全泵?旁有一棵苦楝樹也已死,苦楝樹上有眾多白蟻分布,不知是否有相關...；確認方式：樣本檢驗。', '此官方歷史案例含特定藥劑、濃度或施用方式，可能不符合目前核准用法，系統不直接回傳該舊處方。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-ea94d7056c22a7ddfafea8a4');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (43, 853, '細菌性病害', '症狀：樹發出惡臭，樹皮剝落，逐漸枯死；確認方式：現地診察。', '此官方歷史案例含特定藥劑、濃度或施用方式，可能不符合目前核准用法，系統不直接回傳該舊處方。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-4b0e0ef1f7204d6b7f1eb094');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (44, 855, '褐根病', '症狀：整株枯萎；確認方式：樣本檢驗。', '官方歷史案例建議：防治建議：經分子檢測診斷結果為典型性樹木褐根病危害，為避免造成公共危險，建議連根移除立地進行土壤燻蒸消毒。 1. 掘溝阻斷法：在健康樹與病樹間掘溝深約1公尺，並以強力膠布阻隔後回填土壤，以阻止病根與健康根的接觸傳染。 2. 將受害植株的主根掘起並燒毀。另外可以考慮使用燻蒸劑邁隆，每公頃300-600公斤拌入土中加水後覆蓋塑膠布2星期以上，進行燻蒸。 3. 發病地區可進行1個月的浸水。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-80d0584a81a58a064af1a9c7');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (45, 858, '褐根病', '症狀：大量落葉後,整株枯死,枯木未砍除；確認方式：現地診察。', '官方歷史案例建議：現場勘查為樹木褐根病危害，為避免容易造成公共危險，建議連根移除立地進行土壤燻蒸消毒。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-0563e6cba8a4d0cb8d869def');
