INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (52, 862, '樹木褐根病', '症狀：地基部已出現菌絲；確認方式：現地診察。', '此官方歷史案例含特定藥劑、濃度或施用方式，可能不符合目前核准用法，系統不直接回傳該舊處方。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-a474f47ca6fd5bffe5cd56c4');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (53, 862, '褐根病', '症狀：疑似於移植後,根部附近受灌漿影響,呈現枯竭現象,8/6曾呈報,編號20080350,因即將開學,恐影響學童安全,懇請儘速辦理；確認方式：現地診察。', '官方歷史案例建議：現勘中回覆。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-203e3ba39f0e2450df854fed');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (54, 863, '褐根病', '症狀：枯死；確認方式：樣本檢驗。', '官方歷史案例建議：本所研發有效防治褐根病及燻蒸處理方法。 1. 掘溝阻斷法：在健康樹與病樹間掘溝深約1公尺，並以強力膠布阻隔後回填土壤，以阻止病根與健康根的接觸傳染。 2. 將受害植株的主根掘起並燒毀。另外可以考慮使用燻蒸劑邁隆，每公頃300-600公斤拌入土中加水後覆蓋塑膠布2星期以上，進行燻蒸。 3. 發病地區可進行1個月的浸水。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-ffc71a34bb66ed8c69b21670');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (55, 866, '原因不明', '症狀：底部枝條枝逐漸往上乾枯；確認方式：現地診察。', '官方歷史案例建議：原因不明漸漸嚴重需要追蹤調查 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-8a96ea4992df5bf672c9f3c1');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (56, 868, '褐根病', '症狀：整株枯死，尚未砍除的有2株葉已呈現枯黃，漸掉落；確認方式：現地診察。', '官方歷史案例建議：為樹木褐根病。防治請參考褐根病摺頁資料。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-4f9e8dec5b07ed9ad4d0fb44');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (57, 868, '褐根腐病', '症狀：枝葉稀疏；確認方式：現地診察。', '官方歷史案例建議：車棚旁的兩枯死株砍除並燒毀，這兩株與鄰近健康株及學校側面圍牆旁另外2健康台灣欒樹，建議挖掘1米深的阻絕溝，舖設塑膠布或水泥板後泥土回填。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-e534bf9ee333a0a7d7a26922');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (58, 869, '褐根病', '症狀：大量落葉後整株死亡,立木未砍除；確認方式：現地診察。', '官方歷史案例建議：現場勘查為樹木褐根病危害，為避免容易造成公共危險，建議連根移除立地進行土壤燻蒸消毒。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-dbcf9fe8d9bc997711497e04');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (59, 193, '咖啡銹病', '症狀：咖啡銹病；確認方式：樣本檢驗。', '此官方歷史案例含特定藥劑、濃度或施用方式，可能不符合目前核准用法，系統不直接回傳該舊處方。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-99f0b4c68e4d976519aea7af');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (60, 874, '褐根病', '症狀：全株乾枯、腐壞，而且有擴散情形。；確認方式：現地診察。', '官方歷史案例建議：會勘結果發現校園之榕樹係遭受樹木褐根病危害，為了避免病原繼續擴散感染校園內其他樹木、或造成樹木風倒、甚至無風自倒危及學生安全，建議將病株砍除、病組織徹底清除、燒毀，原種植基地亦建議燻蒸消毒。防治方法請參考附件DVD光碟。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-a3605638521ee1ebea53b6e9');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (61, 875, '褐根病', '症狀：整株枯死亡(已砍除,根部未移除)；確認方式：現地診察。', '官方歷史案例建議：現場勘查為樹木褐根病危害，為避免容易造成公共危險，建議連根移除立地進行土壤燻蒸消毒。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-8592f36e8e0e3eae4504208e');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (62, 877, '癌腫病', '症狀：葉部有紅褐色斑點；確認方式：現地診察。', '官方歷史案例建議：經現場勘查發現 苗木遭受癌腫病危害，因本病對農林生產危害嚴重，為避免經由苗木感染傳播至田間建議將該批苗木銷毀。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-0ff80b1b684b172cdce219f5');
