INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (64, 880, '褐根病', '症狀：根部區塊已有菌絲面長出；確認方式：現地診察。', '官方歷史案例建議：現場勘查為樹木褐根病危害，為避免容易造成公共危險，建議連根移除立地進行土壤燻蒸消毒。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-6f8ca18627a3ad261a70caca');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (65, 881, '褐根病', '症狀：根部腐爛傾倒；確認方式：現地診察。', '此官方歷史案例含特定藥劑、濃度或施用方式，可能不符合目前核准用法，系統不直接回傳該舊處方。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-e7ae7bc3431b7409a93a1ae0');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (66, 882, '褐根病', '症狀：枯死；確認方式：現地診察。', '官方歷史案例建議：會勘結果發現校內夾竹桃係遭受樹木褐根病危害，為了避免病原繼續擴散感染校園內其他樹木，導致樹木風倒、甚至無風自倒危及學生安全，建議將病株砍除、病組織徹底清除、燒毀，原種植基地亦建議燻蒸消毒。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-9b2a42d9c59aaf85e8499e27');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (67, 885, '枝枯病', '症狀：樹葉枯黃；確認方式：樣本檢驗。', '此官方歷史案例含特定藥劑、濃度或施用方式，可能不符合目前核准用法，系統不直接回傳該舊處方。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-50ecab12d6a87226a5072864');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (68, 885, '腐朽菌', '症狀：疑遭白蟻侵襲；確認方式：樣本檢驗。', '官方歷史案例建議：南洋杉的倒伏原因與腐朽菌的入侵有關，在腐朽程度不斷的擴大下，往往會吸引白蟻的進一步啃食，最終則導致樹木傾倒。腐朽菌的入侵又與割草機這類外力所造成的樹木基部傷害有關，爾後應要避免。樟樹看起來目前不需任何防治及處理，南洋杉是否倒伏的疑慮，則建議將主幹生長呈彎曲狀的植株進行支撐，否則可能有不預警倒下的危險存在。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-c49ec85e1b5300f157a5db27');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (69, 885, '褐根病', '症狀：逐漸乾?>；確認方式：現地診察。', '此官方歷史案例含特定藥劑、濃度或施用方式，可能不符合目前核准用法，系統不直接回傳該舊處方。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-5dfb2aff09c4f3cbe7b6452f');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (70, 886, '葉枯病', '症狀：樹幹最先有很小的洞和有白色液體和樹汁 之後就會變成黑色 然後其中一棵的底部有被蟲挖開的現象 這一棵上面炮尷滷〞p特別嚴重 請看下面照片 http://www.hilosi.com/garden/img/treesick1.jpg http://www.hilosi.com/garden/img/treesick2.jpg http://www.hilosi.com/garden/img/treesick3.jpg；確認方式：樣本檢驗。', '此官方歷史案例含特定藥劑、濃度或施用方式，可能不符合目前核准用法，系統不直接回傳該舊處方。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-8cdd279260c46e6b29305e6e');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (71, 887, '癌腫病', '症狀：枝條有腫瘤物；受害描述：.；確認方式：現地診察。', '官方歷史案例建議：建議整株砍除並燒燬，避免感染鄰近健康株。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-f0e4104cf3cc5f890d0ea56a');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (72, 721, '枝枯病', '症狀：末梢樹葉部分枯黃，枝葉略呈黑褐，末端樹葉出汁低到地上引來蒼蠅。；確認方式：樣本檢驗。', '此官方歷史案例含特定藥劑、濃度或施用方式，可能不符合目前核准用法，系統不直接回傳該舊處方。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-e8efd7c3d0200d5d91177f4c');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (73, 892, '木耳', '症狀：全株無萌芽，枝條出現釵h木耳及小型白色靈芝，樹皮有圓狀白色菌斑。；確認方式：樣本檢驗。', '官方歷史案例建議：檢送樣本的腐木長出木耳，木耳為腐生菌，對活樹不會造成危害。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-464fc9ca5f1c80db19940412');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (74, 894, '木層孔菌', '症狀：地上部黃化萎凋。；確認方式：現地診察。', '官方歷史案例建議：因已枯凋死亡，建議移除燒毀。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-e9ce506228e0ba4094e14c9f');
