INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (76, 897, '木材腐朽菌', '症狀：逐漸腐朽；確認方式：現地診察。', '官方歷史案例建議：為木材腐朽菌引起的腐朽。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-c3bbbd610278ad30f604ab3f');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (77, 899, '褐根病', '症狀：大量落葉及枯萎；確認方式：現地診察。', '官方歷史案例建議：現場勘查發現周圍枯萎樹幹有褐根病子實體，建議立即移除燒毀避免擴散，疫區建議加以燻蒸消毒。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-228195b898bdea34277c8a40');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (78, 900, '闊葉樹藻斑病', '症狀：全株葉部枯萎現象；確認方式：現地診察。', '此官方歷史案例含特定藥劑、濃度或施用方式，可能不符合目前核准用法，系統不直接回傳該舊處方。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-396cbffea85e60609bf4b4da');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (79, 902, '褐根病', '症狀：全株枯死；確認方式：現地診察。', '官方歷史案例建議：現場會勘已確定為褐根病 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-80f199e0955a509cbd2314b4');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (80, 903, '褐根病', '症狀：枯死；確認方式：樣本檢驗。', '官方歷史案例建議：防治建議：照片診斷結果為典型性樹木褐根病危害，目前樹木已死亡，為避免造成公共危險，建議連根移除立地進行土壤燻蒸消毒。方法如下： 1. 掘溝阻斷法：在健康樹與病樹間掘溝深約1公尺，並以強力膠布阻隔後回填土壤，以阻止病根與健康根的接觸傳染。 2. 將受害植株的主根掘起並燒毀。另外可以考慮使用燻蒸劑邁隆，每公頃300-600公斤拌入土中加水後覆蓋塑膠布2星期以上，進行燻蒸。 3. 發病地區如不便將主根掘起且該地區具有灌溉系統，可進行1個月的浸水，以殺死存活於殘根的病原菌 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-6b0ba751a6318db5ecc81b6f');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (81, 904, '疑似疫病黃化萎凋', '症狀：生長不良，葉片黃化萎凋；確認方式：現地診察。', '官方歷史案例建議：1. 經過現場會勘，外觀上雖表現疑似罹患疫病之病徵，但觀察莖之地際部與地下根並未呈現褐色腐敗，因此苗木帶病原可能性排除。判斷病因為近來土壤乾燥潮濕交替，氣候變化差異大，造成生理性之黃化萎凋現象。 2. 目前改善方法：重植之新苗，須注意澆水問題，除了避免排水不良積水之問題，尚須注意避免乾燥，乾、溼交雜之下，杜鵑極易發生之現象。 3. 現場已採集樣本，會再做進一&#27497;有無疫病原菌化驗，以確認是否有疫病造成之危害。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-25423c0a595a12a93dac25b7');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (82, 906, '松樹潰瘍病', '症狀：葉片黃化枯萎；確認方式：現地診察。', '此官方歷史案例含特定藥劑、濃度或施用方式，可能不符合目前核准用法，系統不直接回傳該舊處方。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-b1e4e8e4aa33b56063c6dc24');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (83, 906, '葉震病', '症狀：針葉局部黃化或黃化枯萎；受害描述：本病危害葉片。起初在針葉上形成許多黃色或黃褐色的小斑點，而後在病葉上形成一節節黃褐色至褐色的病斑，並有濃褐色之帶狀線，以後葉片逐漸變褐色至灰褐色枯死，在枯死葉上形成細微的黑色斑點，呈橢圓形至紡錘形，稍微突起，此即為病原菌之子囊果;在枯死前之葉上，很少有形成子囊果者。；確認方式：現地診察。', '此官方歷史案例含特定藥劑、濃度或施用方式，可能不符合目前核准用法，系統不直接回傳該舊處方。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-a66eb1696ce3136ea577abf2');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (84, 909, '枝枯病', '症狀：乾葉；確認方式：現地診察。', '此官方歷史案例含特定藥劑、濃度或施用方式，可能不符合目前核准用法，系統不直接回傳該舊處方。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-1d2c514d5afc21c186465adb');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (85, 839, '腐朽菌', '症狀：枯死；確認方式：現地診察。', '官方歷史案例建議：柳樹因天災造成風折倒，腐朽菌於樹幹處滋生，目前該樹木已枯死，建議砍除以維師生的安全。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-799b44e8a8648e8f9781a8ce');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (86, 839, '褐根病', '症狀：整株大量落葉已乾枯，根部已有菌絲面產生；確認方式：現地診察。', '官方歷史案例建議：現場勘查為樹木褐根病危害，為避免容易造成公共危險，建議連根移除立地進行土壤燻蒸消毒。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-8e832931888328254faab34b');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (87, 839, '銹病', '症狀：柳樹葉片有突狀瘤；確認方式：樣本檢驗。', '此官方歷史案例含特定藥劑、濃度或施用方式，可能不符合目前核准用法，系統不直接回傳該舊處方。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-7878de9d52557073648886f5');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (88, 912, '竹簇葉病', '症狀：病枝延伸成多節細長蔓枝,側枝叢生如鳥巢狀．生長勢衰；確認方式：現地診察。', '官方歷史案例建議：十月二十三日現場會勘發現中興新村九二一重建感恩紀念公園內桂竹林係遭受竹簇葉病危害，且竹林老化、生長不良，建議全面更新。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-628b5a8d2272ee53bff86610');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (89, 914, 'Phellinus noxius', '症狀：全株枯死。；確認方式：樣本檢驗。', '官方歷史案例建議：從申請者寄來標本上之病徵發現病株係罹患樹木褐根病，為了避免病原繼續擴散感染校內其他樹木、或造成樹木風倒、甚至無風自倒危及師生安全，建議將病株砍除、疫區內病組織徹底清除、燒毀，原種植基地亦建議燻蒸消毒。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-e7234284b3f2c45a3b13c770');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (90, 914, '褐根病', '症狀：黃化枯萎；確認方式：現地診察。', '此官方歷史案例含特定藥劑、濃度或施用方式，可能不符合目前核准用法，系統不直接回傳該舊處方。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-888f84dc6e769bb203bd1772');
