INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (92, 915, '褐根病', '症狀：枯死之立木已砍除,根部尚未移除；確認方式：現地診察。', '官方歷史案例建議：現場勘查為樹木褐根病危害，為避免容易造成公共危險，建議連根移除立地進行土壤燻蒸消毒。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-78da7e17b7d629920859583b');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (93, 916, '木材腐朽菌', '症狀：底部枝條枝逐漸往上乾枯；確認方式：現地診察。', '官方歷史案例建議：為木材腐朽菌侵蝕腐朽建議施用台肥五號肥加強樹勢生長 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-6a50062395829710d37f4761');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (94, 918, '椰子樹芽腐病', '症狀：有惡臭傳出，頂梢組織腐爛崩解；確認方式：現地診察。', '此官方歷史案例含特定藥劑、濃度或施用方式，可能不符合目前核准用法，系統不直接回傳該舊處方。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-8c021b68e485e25b78417f11');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (95, 920, '褐根病', '症狀：整株葉子掉光，末稍枝幹乾枯、葉子先掉後花朵枯萎。 有灌(三泰芬+撲克拉+救根)的藥液。；確認方式：樣本檢驗。', '官方歷史案例建議：PCR分子檢測診斷結果為典型性樹木褐根病危害，建議連根移除立地進行土壤燻蒸消毒。 方法如下： 1. 掘溝阻斷法：在健康樹與病樹間掘溝深約1公尺，並以強力膠布阻隔後回填土壤，以阻止病根與健康根的接觸傳染。 2. 將受害植株的主根掘起並燒毀。另外可以考慮使用燻蒸劑邁隆，每公頃300-600公斤拌入土中加水後覆蓋塑膠布2星期以上，進行燻蒸。 3. 發病地區可進行1個月的浸水。 此外，林木若生長於貧瘠地可適量施用有機肥，以增加樹木抵抗力。防治期間，請同時注意加強管理樹木倒伏之危險 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-d42b67859bd97a34fe184d16');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (96, 921, '褐根病', '症狀：葉子黃化掉落；確認方式：現地診察。', '官方歷史案例建議：為樹木褐根病。防治請參考褐根病摺頁資料。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-48e15eb64637e92097c3f6f4');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (97, 922, '褐根病', '症狀：整株枯死已砍除，根部並未移除，已有菌絲面產生；確認方式：現地診察。', '官方歷史案例建議：為避免容易造成公共危險，建議連根移除立地進行土壤燻蒸消毒。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-448b50da15f140443820cb1e');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (98, 924, '褐根病', '症狀：疑似褐根病；確認方式：樣本檢驗。', '此官方歷史案例含特定藥劑、濃度或施用方式，可能不符合目前核准用法，系統不直接回傳該舊處方。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-ccae0f213ce9605c751449d9');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (99, 925, '可能已被感染褐根病', '症狀：生長勢略差；確認方式：現地診察。', '官方歷史案例建議：此榕樹生長地點正好在兩棵罹患褐根病之榕樹旁，雖然會勘後並未在植株地際部找到病徵，但本植株地底根部末端應與鄰近病株根系有接觸，從生長狀況判斷，末端根系極有可能已被感染，若能盡快處理已罹病植株，或野i保有此植株。除了生長方面，此植株在基部的一分枝腐朽嚴重，建議移除以免倒下傷人。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-6f57067d51ed673e59518e83');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (100, 925, '孔洞木材腐朽', '症狀：孔洞木材腐朽；確認方式：現地診察。', '官方歷史案例建議：樹幹孔洞木材腐朽，但非病原性菌類危害。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-0dece66bbd7bf3ba28538b65');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (101, 925, '木材腐朽病', '症狀：莖基部孔洞腐朽；確認方式：現地診察。', '官方歷史案例建議：屬腐生性腐朽，不會引起立即性的枯死。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-8ad83974f9b105e353f83b5b');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (102, 925, '根腐病', '症狀：根及莖基部腐朽；確認方式：現地診察。', '官方歷史案例建議：但病原菌有待確定 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-1d34c65aba87df4d094f50e0');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (103, 925, '樹木褐根病', '症狀：落葉、泵?>；確認方式：現地診察。', '官方歷史案例建議：會勘結果發現校園之榕樹係遭受樹木褐根病危害，且一棵已傾倒。此病原除了會造成樹木炸銦B死亡外，同時也為一腐朽菌，染病樹木根部會快速腐朽而失去其物理結構與支撐，最後無預警的倒下。樹木褐根病病原具傳染性，健康樹木之根部若與病根接觸，也會罹患此病。為了避免樹木倒下危及校內師生安全、也為了避免病原繼續擴散感染校園內其他樹木，建議將病株砍除、土壤內病組織徹底清除、燒毀，原種植基地亦建議燻蒸消毒。防治方法請參考附件DVD光碟。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-2037af7583f21861fdb834b7');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (104, 925, '煤煙病', '症狀：葉片都布滿黑色類似燒焦的麻點；確認方式：現地診察。', '此官方歷史案例含特定藥劑、濃度或施用方式，可能不符合目前核准用法，系統不直接回傳該舊處方。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-e5d12bf05ca6a0635a6e1605');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (105, 925, '紫膠介殼蟲與煤煙病', '症狀：葉面上蒙上一層黑色污垢；確認方式：現地診察。', '此官方歷史案例含特定藥劑、濃度或施用方式，可能不符合目前核准用法，系統不直接回傳該舊處方。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-0e7d694f8723a295dd65fb84');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (106, 925, '腐朽菌', '症狀：主幹腐朽；確認方式：現地診察。', '官方歷史案例建議：腐朽並不嚴重可不處理，但要保持乾燥。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-a1432ebd9d6598245fceb280');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (107, 925, '褐根病', '症狀：這是一棵大概三人環抱的老榕樹，樹葉稀疏，今年春天並無冒出新芽。根部有些褐色的面積，有一部份的根部感覺已腐蝕。；確認方式：樣本檢驗。', '此官方歷史案例含特定藥劑、濃度或施用方式，可能不符合目前核准用法，系統不直接回傳該舊處方。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-785d828f1b178fe5f0ede21b');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (108, 925, '褐根腐病', '症狀：枝條葉片枯萎黃化；確認方式：現地診察。', '此官方歷史案例含特定藥劑、濃度或施用方式，可能不符合目前核准用法，系統不直接回傳該舊處方。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-15ca6e4cffde05854019eb2c');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (109, 925, '靈芝根基腐朽病', '症狀：靈芝危害；確認方式：現地診察。', '官方歷史案例建議：本病害的防治方法與褐根病相同。另外，因靈芝常形成子實體並產生大量擔孢子飛散傳播。防治上，除褐根病的方法外，可增加下列方法： 1.子實體清除法：在林地將初生的子實體清除，減少擔孢子的形成及傳播，以減少初次感染源。 2.盡量避免造成植株人為傷口，因擔孢子是經由植株的傷口感染，減少人為傷口可以降低新的感染機會，如除草或其它作業造成之傷口。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-e1c42e94e2adac7dae136c2c');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (110, 925, '鮑魚菇', '症狀：基部有菇體；確認方式：現地診察。', '此官方歷史案例含特定藥劑、濃度或施用方式，可能不符合目前核准用法，系統不直接回傳該舊處方。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-d54f9b41bcb23d63661b8b08');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (111, 926, '樹木褐根病', '症狀：全株枯死；確認方式：現地診察。', '官方歷史案例建議：會勘結果發現中央印製廠內槭樹係遭受樹木褐根病危害，為了避免病原繼續擴散感染印製廠內其他樹木，導致樹木風倒、甚至無風自倒危及廠區人員安全，建議將病株砍除、病組織徹底清除、燒毀，原種植基地亦建議燻蒸消毒。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-c88c601e4259cf1e9314fd63');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (112, 927, '褐根病', '症狀：樹木分別逐漸枯死，似乎有傳染性；確認方式：樣本檢驗。', '官方歷史案例建議：樣本檢驗結果為樹木褐根病危害，為避免容易造成公共危險，建議連根移除立地進行土壤燻蒸消毒。方法如下： 1.掘溝阻斷法：在健康樹與病樹間掘溝深約1公尺，並以強力膠布阻隔後回填土壤，以阻止病根與健康根的接觸傳染。 2.將受害植株的主根掘起並燒毀。另外可以考慮使用燻蒸劑邁隆，每公頃300-600公斤拌入土中加水後覆蓋塑膠布2星期以上，進行燻蒸。 3.發病地區如不便將主根掘起且該地區具有灌溉系統，可進行1個月的浸水，以殺死存活於殘根的病原菌。 提供您邁隆的廠商：嘉泰企業 姓名：詹大玄 電話：0912749994 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-19c42ee60fb0707571f3e8b9');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (113, 928, '樣本無褐根病病原', '症狀：落葉泵?>；確認方式：樣本檢驗。', '此官方歷史案例含特定藥劑、濃度或施用方式，可能不符合目前核准用法，系統不直接回傳該舊處方。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-9d6806b4516c89de6feded6c');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (114, 928, '樹木褐根病', '症狀：整株枯死；確認方式：現地診察。', '官方歷史案例建議：會勘結果發現校內樟樹係遭受樹木褐根病危害,為避免病害擴散危害周圍樹木.病株有風倒或無風自倒危及學生安全,建議立刻將病株掘起.病組織徹底燒毀,原種植基地亦建議燻蒸消毒 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-409b19fe88d65e4fd2cf0725');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (115, 928, '腐朽菌', '症狀：疑遭白蟻侵襲；確認方式：樣本檢驗。', '官方歷史案例建議：南洋杉的倒伏原因與腐朽菌的入侵有關，在腐朽程度不斷的擴大下，往往會吸引白蟻的進一步啃食，最終則導致樹木傾倒。腐朽菌的入侵又與割草機這類外力所造成的樹木基部傷害有關，爾後應要避免。樟樹看起來目前不需任何防治及處理，南洋杉是否倒伏的疑慮，則建議將主幹生長呈彎曲狀的植株進行支撐，否則可能有不預警倒下的危險存在。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-a59405ae3356409216fd791d');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (116, 928, '褐根病', '症狀：根部有菌絲；確認方式：樣本檢驗。', '官方歷史案例建議：所送檢體經檢驗為樹木褐根病危害，防治方法請參考「認識樹木褐根病」摺頁資料。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-f637331227c8d79c6b476e4a');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (117, 930, '褐根病', '症狀：黃化、萎凋、死亡；確認方式：現地診察。', '官方歷史案例建議：橡膠樹發病嚴重，建議移除。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-7bab0c11a8c690abd8c6e3a8');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (118, 513, '熱帶靈芝', '症狀：根腐長出的菇體。；確認方式：現地診察。', '官方歷史案例建議：因已枯死，不做防治建議。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-219504df65462f04913d7a78');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (119, 933, '癌腫病', '症狀：葉炸銝邪重彄蒡閬漱`；確認方式：樣本檢驗。', '官方歷史案例建議：樣品經過鑑定，確認感染癌腫病。 癌腫病因有潛伏期，為避免病害擴散，建議將病株一併進行銷毀及危害地區施行燻蒸處理。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-3f9ac2bed5712d27390cf54f');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (120, 935, '簇葉病', '症狀：簇葉情形；確認方式：樣本檢驗。', '此官方歷史案例含特定藥劑、濃度或施用方式，可能不符合目前核准用法，系統不直接回傳該舊處方。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-3b06754e60aa67e4f2b9a079');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (121, 935, '細菌性或Cercospora sp.角斑', '症狀：樹幹部分蛀蝕的小洞，洞深達十多公分以上。樹葉部份另有出現斑點。；確認方式：現地診察。', '此官方歷史案例含特定藥劑、濃度或施用方式，可能不符合目前核准用法，系統不直接回傳該舊處方。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-5f86d70af15c769008c882db');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (122, 935, '褐根病', '症狀：葉子不斷掉落，並無長出新芽；確認方式：樣本檢驗。', '此官方歷史案例含特定藥劑、濃度或施用方式，可能不符合目前核准用法，系統不直接回傳該舊處方。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-f2d9bfb272420e33f60655c2');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (123, 936, '白紋羽病', '症狀：新種植接陸續枯死；確認方式：現地診察。', '官方歷史案例建議：依植穴檢查結果為櫻花白紋羽病，防治建議請參考台灣常見樹木病害樹木白紋羽病之資料。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-6399d963d53611473eb34a10');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (124, 936, '白蟻及褐根病', '症狀：落葉；確認方式：現地診察。', '此官方歷史案例含特定藥劑、濃度或施用方式，可能不符合目前核准用法，系統不直接回傳該舊處方。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-d0fe1f5a3b32f00fa691fb0f');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (125, 936, '細菌性癌腫病', '症狀：腫瘤狀；確認方式：現地診察。', '官方歷史案例建議：建議應砍除銷毀避免疫情擴大 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-b9db9590eae890f1d1bc3272');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (126, 937, '褐褐病', '症狀：枯死；確認方式：樣本檢驗。', '官方歷史案例建議：本所研發有效防治褐根病及燻蒸處理方法。 1. 掘溝阻斷法：在健康樹與病樹間掘溝深約1公尺，並以強力膠布阻隔後回填土壤，以阻止病根與健康根的接觸傳染。 2. 將受害植株的主根掘起並燒毀。另外可以考慮使用燻蒸劑邁隆，每公頃300-600公斤拌入土中加水後覆蓋塑膠布2星期以上，進行燻蒸。 3. 發病地區可進行1個月的浸水。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-dadd130b46a3171000a9660b');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (127, 938, '褐根病', '症狀：葉子黃化掉落；確認方式：現地診察。', '官方歷史案例建議：為樹木褐根病。防治請參考褐根病摺頁資料。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-fe40bb72d3b015090dde605d');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (128, 939, '褐根病', '症狀：整株已枯死；確認方式：現地診察。', '官方歷史案例建議：為樹木褐根病。防治請參考褐根病摺頁資料。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-84cffe8e64c569535e44c675');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (129, 940, '褐根病', '症狀：枯死；確認方式：樣本檢驗。', '官方歷史案例建議：本所研發有效防治褐根病及燻蒸處理方法。 1. 掘溝阻斷法：在健康樹與病樹間掘溝深約1公尺，並以強力膠布阻隔後回填土壤，以阻止病根與健康根的接觸傳染。 2. 將受害植株的主根掘起並燒毀。另外可以考慮使用燻蒸劑邁隆，每公頃300-600公斤拌入土中加水後覆蓋塑膠布2星期以上，進行燻蒸。 3. 發病地區可進行1個月的浸水。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-df62ae97de29e8185f4deba6');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (130, 942, '褐根病', '症狀：根際部腐朽；確認方式：樣本檢驗。', '此官方歷史案例含特定藥劑、濃度或施用方式，可能不符合目前核准用法，系統不直接回傳該舊處方。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-4e314384adcf827d89ccdcbc');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (131, 943, '褐根病', '症狀：葉子大量落葉黃化，根部已有菌絲面產生；確認方式：現地診察。', '官方歷史案例建議：為避免容易造成公共危險，建議連根移除立地進行土壤燻蒸消毒。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-421d26d35a6765afb33bc481');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (132, 944, '葉枯病', '症狀：樹幹最先有很小的洞和有白色液體和樹汁 之後就會變成黑色 然後其中一棵的底部有被蟲挖開的現象 這一棵上面炮尷滷〞p特別嚴重 請看下面照片 http://www.hilosi.com/garden/img/treesick1.jpg http://www.hilosi.com/garden/img/treesick2.jpg http://www.hilosi.com/garden/img/treesick3.jpg；確認方式：樣本檢驗。', '此官方歷史案例含特定藥劑、濃度或施用方式，可能不符合目前核准用法，系統不直接回傳該舊處方。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-a6f7a98be358435219654596');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (133, 945, '褐根病', '症狀：枯死；確認方式：樣本檢驗。', '官方歷史案例建議：本所研發有效防治褐根病及燻蒸處理方法。 1. 掘溝阻斷法：在健康樹與病樹間掘溝深約1公尺，並以強力膠布阻隔後回填土壤，以阻止病根與健康根的接觸傳染。 2. 將受害植株的主根掘起並燒毀。另外可以考慮使用燻蒸劑邁隆，每公頃300-600公斤拌入土中加水後覆蓋塑膠布2星期以上，進行燻蒸。 3. 發病地區可進行1個月的浸水。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-e03e5ad65d67152d578b9238');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (134, 947, '褐根病', '症狀：火焰木及艷紫荊葉子稀疏枝條逐漸炸? 榕樹今年未換新葉並逐漸稀疏；確認方式：樣本檢驗。', '此官方歷史案例含特定藥劑、濃度或施用方式，可能不符合目前核准用法，系統不直接回傳該舊處方。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-5a054888330b354387d29f24');
