INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (136, 825, '炭疽病', '症狀：葉片有褐斑；確認方式：樣本檢驗。', '官方歷史案例建議：使用防治炭疽病的殺菌劑。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-6d59af99df6b2046ef6645e5');
