INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (144, 710, '真菌腐朽性病害', '症狀：樹幹腐朽；確認方式：現地診察。', '此官方歷史案例含特定藥劑、濃度或施用方式，可能不符合目前核准用法，系統不直接回傳該舊處方。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-af67a75a73659e40a477270f');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (145, 21, '玫瑰黑斑病', '症狀：黑點 落葉 生長不良；確認方式：現地診察。', '此官方歷史案例含特定藥劑、濃度或施用方式，可能不符合目前核准用法，系統不直接回傳該舊處方。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-09c634cda5fd86442033dc75');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (146, 951, '褐根病', '症狀：整株葉子掉光，末稍枝幹乾枯、葉子先掉後花朵枯萎。 有灌(三泰芬+撲克拉+救根)的藥液。；確認方式：樣本檢驗。', '官方歷史案例建議：PCR分子檢測診斷結果為典型性樹木褐根病危害，建議連根移除立地進行土壤燻蒸消毒。 方法如下： 1. 掘溝阻斷法：在健康樹與病樹間掘溝深約1公尺，並以強力膠布阻隔後回填土壤，以阻止病根與健康根的接觸傳染。 2. 將受害植株的主根掘起並燒毀。另外可以考慮使用燻蒸劑邁隆，每公頃300-600公斤拌入土中加水後覆蓋塑膠布2星期以上，進行燻蒸。 3. 發病地區可進行1個月的浸水。 此外，林木若生長於貧瘠地可適量施用有機肥，以增加樹木抵抗力。防治期間，請同時注意加強管理樹木倒伏之危險 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-807b0cdd552d838f6f7ad4a9');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (147, 953, '褐斑病', '症狀：葉片呈黃斑狀；確認方式：樣本檢驗。', '此官方歷史案例含特定藥劑、濃度或施用方式，可能不符合目前核准用法，系統不直接回傳該舊處方。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-398cf8030805fe923432f0f2');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (148, 954, '褐根病', '症狀：大量落葉而枯死 樹木傾倒；確認方式：現地診察。', '官方歷史案例建議：褐根病菌除了是樹木重要的病原菌外亦是木材腐朽菌，除了讓樹木立枯枯萎外由於其具木材腐朽的能力，防治請參考褐根病摺頁資料。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-6d6081f84354d36a40963a17');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (149, 959, '癌腫病', '症狀：葉部有紅褐色斑點；確認方式：現地診察。', '官方歷史案例建議：經現場勘查發現 苗木遭受癌腫病危害，因本病對農林生產危害嚴重，為避免經由苗木感染傳播至田間建議將該批苗木銷毀。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-b4347ad39f84d2ef0b6a2f32');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (150, 959, '褐根病', '症狀：根部有菌絲現象。(蔡宜修先生、謝鴻銘先生、傅春旭先生曾到校取樣，97.11.25-26除辦理研習外亦處理學校受感染之林木)；確認方式：現地診察。', '官方歷史案例建議：為樹木褐根病感染，因位於校園學生及教職員活動區域，日後恐有倾倒的公共危險，建議砍除，植穴燻蒸消毒後再行種植。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-011655c02004a025891e708a');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (151, 959, '褐根腐病', '症狀：枝條葉片枯萎黃化；確認方式：現地診察。', '官方歷史案例建議：健康株與外側2病株中間處可挖掘1米深的阻絕溝，舖設塑膠布或水泥板後泥土回填即可。枯死株建議砍除並燒燬，避免倒伏發生危險。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-b1451eb521cf6ed7241f5fab');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (152, 959, '褐根腐病、生理反應', '症狀：全株枯萎；確認方式：現地診察。', '官方歷史案例建議：士文村場村長所屬之已開墾（約0.5公頃）周圍的相思樹,經95年12月26日現場採樣,病原菌培養後確認為褐根腐菌,建議該區進行褐根病的防治及土壤薰蒸（見推廣摺頁）後,方可重新栽植新苗木。造林地部分並未發現可導致枯萎的病蟲害存在,枯萎現象與植物生理反應有關,包括氣候、水分等因子都可能影響,故無須任何的病蟲害防治措施,建議每月監測一次並紀錄枯萎株樹,以暸解枯萎範圍是否擴大。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-4030cb9440ca78ef574cd9e0');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (153, 960, '樹木褐根病', '症狀：整株枯死；確認方式：現地診察。', '官方歷史案例建議：現場勘查為樹木褐根病危害，為避免容易造成公共危險，建議連根移除立地進行土壤燻蒸消毒。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-ec81fd219b7170373497696e');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (154, 960, '褐根病', '症狀：整株枯死；確認方式：現地診察。', '官方歷史案例建議：為樹木褐根病。防治請參考褐根病摺頁資料。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-22fc7386f48c5b40765f2746');
