INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (157, 966, '摺菌', '症狀：莖、枝葉均腐爛掉落；確認方式：樣本檢驗。', '官方歷史案例建議：該林投樹已枯死建議砍除，摺菌可能為二次感染，並非真正死因。請協助採取部份樹基部及根部樣本，郵寄本中心以利病原菌培養確認致死原因。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-11fab998144104a9d1c115c9');
