INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (164, 972, '褐根病', '症狀：已乾枯死亡，根部已有菌絲面產生；確認方式：現地診察。', '官方歷史案例建議：現場勘查為樹木褐根病危害，為避免容易造成公共危險，建議連根移除立地進行土壤燻蒸消毒。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-73b5263f633857a510841129');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (165, 260, '褐根病', '症狀：大量落葉其中2株已經枯死予砍除，根部尚未移除；確認方式：現地診察。', '官方歷史案例建議：現場勘查為樹木褐根病危害，容易造成公共危險及感染源，建議連根移除立地進行土壤燻蒸消毒。防治請參考褐根病摺頁資料。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-7f9888836c1a42b0b2fca17e');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (166, 973, '褐根病', '症狀：整棵樹木呈現炬聹{象，已有半年的時間。；確認方式：樣本檢驗。', '此官方歷史案例含特定藥劑、濃度或施用方式，可能不符合目前核准用法，系統不直接回傳該舊處方。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-9cfbe8ebaee954cb1579c12d');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (167, 828, '疫病根腐', '症狀：全株枯萎；確認方式：現地診察。', '官方歷史案例建議：利用亞磷酸防治，詳細方法已另外提供。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-fcf6880cfaad3f22e81f0e15');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (168, 828, '肖楠病', '症狀：整株枯死；受害描述：會勘結果發現肖楠係遭受肖楠病感染,為避免擴散,建議將病株連根移除.本病喜發生於排水不良的環境.；確認方式：現地診察。', '此官方歷史案例含特定藥劑、濃度或施用方式，可能不符合目前核准用法，系統不直接回傳該舊處方。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-035dcbc4c2a7fd4aaaefcad7');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (169, 975, '樹木褐根病', '症狀：整株枯死；確認方式：現地診察。', '官方歷史案例建議：會勘結果發現校內肯式南洋杉係遭受樹木褐根病危害,為避免病害擴散危害周圍樹木.病株有風倒或無風自倒危及學生安全,建議立刻將病株掘起.病組織徹底燒毀,原種植基地亦建議燻蒸消毒 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-d0ad1c74a6102872d018e0e0');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (170, 975, '褐根病', '症狀：葉萎枯落、根皮腐壞立姿而枯；確認方式：樣本檢驗。', '官方歷史案例建議：樣本檢驗結果為樹木褐根病危害，為避免容易造成公共危險，建議連根移除立地進行土壤燻蒸消毒。方法如下： 1.掘溝阻斷法：在健康樹與病樹間掘溝深約1公尺，並以強力膠布阻隔後回填土壤，以阻止病根與健康根的接觸傳染。 2.將受害植株的主根掘起並燒毀。另外可以考慮使用燻蒸劑邁隆，每公頃300-600公斤拌入土中加水後覆蓋塑膠布2星期以上，進行燻蒸。 3. 發病地區如不便將主根掘起且該地區具有灌溉系統，可進行1個月的浸水，以殺死存活於殘根的病原菌。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-6ece399843b182b606e66f5e');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (172, 978, '癌腫病', '症狀：莖幹褐紅色，有疑似瘤組織，枯死；確認方式：樣本檢驗。', '官方歷史案例建議：卓蘭苗圃，原本之11萬7仟株於95年3月底已搬移4萬3仟株至東勢新石角苗圃培養，剩餘之7萬4仟株發現有枯死及生長不良之現象，並有感染細菌係癌腫病，移至新石角苗圃之苦楝雖然目前並無發現有受危害，惟感染細菌係癌腫病因有潛伏期，為避免病害擴散建議一併進行銷毀及苗圃燻蒸處理。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-90b50106ee857abb74373d29');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (173, 978, '細菌性癌腫病', '症狀：莖幹褐紅色，且有瘤似的組織；確認方式：現地診察。', '官方資料未提供可直接套用的處置方式。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-a08a1c0951f95e575a8cf8aa');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (174, 978, '褐根病', '症狀：大量落葉,葉子黃化,根基部已出現菌絲面；確認方式：現地診察。', '官方歷史案例建議：現場勘查為樹木褐根病危害，為避免容易造成公共危險，建議連根移除立地進行土壤燻蒸消毒。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-80a00335a70a8e4065d8eac3');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (175, 979, '褐根病', '症狀：全株枯死；確認方式：現地診察。', '官方歷史案例建議：現場會勘已確定為褐根病 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-eb003e8beccf989a8bce4f2d');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (176, 980, '枝枯病', '症狀：不明原因葉子枯黃，掉落，同時栽種的另一群皆為正常‧；確認方式：現地診察。', '此官方歷史案例含特定藥劑、濃度或施用方式，可能不符合目前核准用法，系統不直接回傳該舊處方。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-9dc6346ea3cf1448ae74e0b8');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (177, 980, '炭疽病', '症狀：枯黃。；確認方式：樣本檢驗。', '此官方歷史案例含特定藥劑、濃度或施用方式，可能不符合目前核准用法，系統不直接回傳該舊處方。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-87915699731f48b80b64316b');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (178, 980, '褐根病', '症狀：逐漸乾枯傾倒；確認方式：現地診察。', '此官方歷史案例含特定藥劑、濃度或施用方式，可能不符合目前核准用法，系統不直接回傳該舊處方。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-3bca69b73d327cd7f592c32e');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (179, 980, '闊葉樹藻斑病', '症狀：植株頂部枝葉枯乾。；確認方式：現地診察。', '官方歷史案例建議：由樹木枝條枯萎狀況研判，為藻體造成的藻斑病危害，土壤積水也有助此病害發生。應適當修剪枝條減輕病害發生機會。 一般而言，藻類對銅離子敏感，所以可用銅劑防治。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-cd851805344488e313c88168');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (180, 981, '腐生性危害', '症狀：50年茶花樹，主幹發霉、分枝炸銂囓捰滫熊?>；確認方式：樣本檢驗。', '官方歷史案例建議：部分主幹已腐朽而引起腐生性的甲蟲(如小蠹蟲)進行鑽蛀，白色的絲為紅蜘蛛類的&#34766;蜱所盤絲而成直接去除即可。這兩類生物都不會影響茶樹的生長。該茶樹其他部位有腐朽現象應立即鋸除，以避免腐朽的擴大。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-bf3fcb899f93410fb6bc2f62');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (181, 982, '炭疽病、寒害', '症狀：葉部出縣黃色及紫色並在葉部有很明顯的痕跡；確認方式：樣本檢驗。', '此官方歷史案例含特定藥劑、濃度或施用方式，可能不符合目前核准用法，系統不直接回傳該舊處方。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-ac17d458e9f5c525b2591dfe');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (182, 985, '褐根病', '症狀：整株葉子掉光，末梢枝幹乾枯，葉子先掉後花朵枯萎；確認方式：樣本檢驗。', '官方歷史案例建議：PCR分子檢測診斷結果為典型性樹木褐根病危害，建議連根移除立地進行土壤燻蒸消毒。 方法如下： 1. 掘溝阻斷法：在健康樹與病樹間掘溝深約1公尺，並以強力膠布阻隔後回填土壤，以阻止病根與健康根的接觸傳染。 2. 將受害植株的主根掘起並燒毀。另外可以考慮使用燻蒸劑邁隆，每公頃300-600公斤拌入土中加水後覆蓋塑膠布2星期以上，進行燻蒸。 3. 發病地區可進行1個月的浸水。 此外，林木若生長於貧瘠地可適量施用有機肥，以增加樹木抵抗力。防治期間，請同時注意加強管理樹木倒伏之危險 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-0fa5a5c6761c36ac54b87d02');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (183, 986, '褐根病', '症狀：整株葉子掉光，末稍枝幹乾枯、葉子先掉後花朵枯萎。 有灌(三泰芬+撲克拉+救根)的藥液。；確認方式：樣本檢驗。', '官方歷史案例建議：PCR分子檢測診斷結果為典型性樹木褐根病危害，建議連根移除立地進行土壤燻蒸消毒。 方法如下： 1. 掘溝阻斷法：在健康樹與病樹間掘溝深約1公尺，並以強力膠布阻隔後回填土壤，以阻止病根與健康根的接觸傳染。 2. 將受害植株的主根掘起並燒毀。另外可以考慮使用燻蒸劑邁隆，每公頃300-600公斤拌入土中加水後覆蓋塑膠布2星期以上，進行燻蒸。 3. 發病地區可進行1個月的浸水。 此外，林木若生長於貧瘠地可適量施用有機肥，以增加樹木抵抗力。防治期間，請同時注意加強管理樹木倒伏之危險 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-5bbdc0d3761c60c0d119a79a');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (184, 987, 'Phellinus noxius', '症狀：全株枯死。；確認方式：樣本檢驗。', '官方歷史案例建議：從申請者寄來標本上之病徵發現病株係罹患樹木褐根病，為了避免病原繼續擴散感染校內其他樹木、或造成樹木風倒、甚至無風自倒危及師生安全，建議將病株砍除、疫區內病組織徹底清除、燒毀，原種植基地亦建議燻蒸消毒。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-0e75de7ec0477ea56664d0e1');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (185, 988, '褐根病', '症狀：樹葉枯黃掉落；確認方式：樣本檢驗。', '官方歷史案例建議：防治建議：分子檢測診斷結果為典型性樹木褐根病危害，目前樹木已死亡，為避免造成公共危險，建議連根移除立地進行土壤燻蒸消毒。方法如下： 1. 掘溝阻斷法：在健康樹與病樹間掘溝深約1公尺，並以強力膠布阻隔後回填土壤，以阻止病根與健康根的接觸傳染。 2. 將受害植株的主根掘起並燒毀。另外可以考慮使用燻蒸劑邁隆，每公頃300-600公斤拌入土中加水後覆蓋塑膠布2星期以上，進行燻蒸。 3. 發病地區如不便將主根掘起且該地區具有灌溉系統，可進行1個月的浸水，以殺死存活於殘根的病原菌。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-2ecfa70311222f8f6514c47c');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (186, 988, '黑脂病', '症狀：種植區域部分成長枝葉茂盛，部分似營養不良。；確認方式：現地診察。', '此官方歷史案例含特定藥劑、濃度或施用方式，可能不符合目前核准用法，系統不直接回傳該舊處方。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-10d22ed75ae942aa3ac9befb');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (187, 988, '黑腫病', '症狀：葉片有黑點狀；確認方式：現地診察。', '此官方歷史案例含特定藥劑、濃度或施用方式，可能不符合目前核准用法，系統不直接回傳該舊處方。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-314b98c49181e9d1972ed439');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (188, 991, '樹木褐根病', '症狀：根部已出現菌絲面；確認方式：現地診察。', '此官方歷史案例含特定藥劑、濃度或施用方式，可能不符合目前核准用法，系統不直接回傳該舊處方。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-156ab9b8e7ad030300d39274');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (189, 993, '黃龍病', '症狀：逐漸生長不良；確認方式：現地診察。', '官方歷史案例建議：為柑橘黃龍病。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-3c2427d7bd6dc88debd417eb');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (190, 994, '褐根病', '症狀：根部腐朽；確認方式：樣本檢驗。', '官方歷史案例建議：經由標本病徵發現中央研究院歷史語言研究所研究大樓前之豔紫荊係遭受樹木褐根病危害。由於罹病樹木根部會漸漸腐朽，造成風倒甚至無風自倒的情況，為了院內同仁活動安全起見，以及避免病原繼續擴散，建議將病株連跟掘起、病組織徹底移除燒毀，原種植地亦建議燻蒸消毒。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-bc713f9efe23e2af99c9caf6');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (191, 995, '煤煙病', '症狀：煤煙狀，落葉；確認方式：樣本檢驗。', '官方資料未提供可直接套用的處置方式。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-e626c0eb87fd82700207dd8b');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (192, 522, '褐根病', '症狀：泵滿B已砍除；確認方式：現地診察。', '官方歷史案例建議：經會勘發現，南瀛總爺藝文中心園區內之酪梨係罹患樹木褐根病。引起樹木褐根病之病原Phellinus noxius具傳染性，可藉根與根的接觸傳染。Phellinus noxius除了為病原菌、可使樹木染病、死亡外，也是一種木材腐朽菌，使罹病植株之木材腐朽、鬆軟、失去其物理結構。園區內染病之酪梨雖已砍除，但為了避免鄰近健康植株的根系接觸未清除的病根而受到傳染，建議將罹病酪梨原種植地內之病根徹底挖除、殘根完全撿拾，並將土壤燻蒸處理。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-97efd5c0206f6511077c497c');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (193, 999, '褐根病', '症狀：整株樹葉於短期內迅速枯萎凋落，顏色變黑。；確認方式：現地診察。', '官方歷史案例建議：樣本檢驗結果為樹木褐根病危害，為避免容易造成公共危險，建議連根移除立地進行土壤燻蒸消毒。方法如下： 1.掘溝阻斷法：在健康樹與病樹間掘溝深約1公尺，並以強力膠布阻隔後回填土壤，以阻止病根與健康根的接觸傳染。 2.將受害植株的主根掘起並燒毀。另外可以考慮使用燻蒸劑邁隆，每公頃300-600公斤拌入土中加水後覆蓋塑膠布2星期以上，進行燻蒸。 3.發病地區如不便將主根掘起且該地區具有灌溉系統，可進行1個月的浸水，以殺死存活於殘根的病原菌。 提供您邁隆的廠商：嘉泰企業 電話：03-4501297 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-9f6d8c9b1ea88b8cf90ce238');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (194, 1005, '褐根腐病', '症狀：枝葉稀疏；確認方式：現地診察。', '官方歷史案例建議：枯死株砍除並燒毀，這3株與鄰近健康株，建議挖掘1米深的阻絕溝，舖設塑膠布或水泥板後泥土回填。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-68e72d460222e99338ea0eec');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (195, 1006, '褐根病', '症狀：枯死；確認方式：樣本檢驗。', '官方歷史案例建議：本所研發有效防治褐根病及燻蒸處理方法。 1. 掘溝阻斷法：在健康樹與病樹間掘溝深約1公尺，並以強力膠布阻隔後回填土壤，以阻止病根與健康根的接觸傳染。 2. 將受害植株的主根掘起並燒毀。另外可以考慮使用燻蒸劑邁隆，每公頃300-600公斤拌入土中加水後覆蓋塑膠布2星期以上，進行燻蒸。 3. 發病地區可進行1個月的浸水。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-1d1cd5890439b90c508480d1');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (196, 1007, '褐根病', '症狀：如附檢體；確認方式：現地診察。', '官方歷史案例建議：感染褐根病之樹木，樹根易腐朽、倒塌，為避免其倒塌壓傷人員或繼續感染周圍的樹種(褐根病可經由樹根接觸而感染健康的植株)，須將感染死亡的樹木盡快移除，並將土內的病根、殘根清除乾淨，不可棄置原地(若殘根未撿除乾淨，燻蒸效果會較差，病原菌易殘存在較大的樹根內)；此外，建議再將病土利用”邁隆燻蒸劑”作土壤燻蒸處理。由於燻蒸過後的土壤會變成”死土”(因邁隆會將土壤中的微生物和蚯蚓等生物殺死)，因此，燻蒸後需再添加有機肥，以恢復土壤中的生物活性。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-8d699bfcbff2ae7d6e3291d9');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (197, 1009, '白粉病', '症狀：幼葉遭病蟲危害，新芽萎縮；確認方式：樣本檢驗。', '官方歷史案例建議：已將防治方法e-mail給申請人。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-ef85827a81b923fa7f066600');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (198, 1010, '褐根病', '症狀：整株不正常的落葉，根部已有菌絲面產生；確認方式：現地診察。', '官方歷史案例建議：現場勘查為樹木褐根病危害，為避免容易造成公共危險，建議連根移除立地進行土壤燻蒸消毒。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-6e0290bf5a2b1ec054c1a518');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (199, 1011, '褐根病', '症狀：葉面部分枯黃，致根部腐爛；確認方式：樣本檢驗。', '官方歷史案例建議：經分子檢測診斷結果為典型性樹木褐根病危害，為避免造成公共危險，建議連根移除立地進行土壤燻蒸消毒。 1.掘溝阻斷法：在健康樹與病樹間掘溝深約1公尺，並以強力膠布阻隔後回填土壤，以阻止病根與健康根的接觸傳染。 2.將受害植株的主根掘起並燒毀。另外可以考慮使用燻蒸劑邁隆，每公頃300-600公斤拌入土中加水後覆蓋塑膠布2星期以上，進行燻蒸。 3.發病地區可進行1個月的浸水。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-e8e8f2ba06444e8cb24d8d6f');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (200, 1012, '樹木褐根病', '症狀：2株死亡根部已移除，根部已有菌絲面產生；確認方式：現地診察。', '官方歷史案例建議：現場勘查為樹木褐根病危害，為避免容易造成公共危險，建議連根移除立地進行土壤燻蒸消毒。 因與海青商職只臨近一條馬路，在九十五年間有在海青查獲子實體 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-558dbde8efc3de1a49d7d7d9');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (201, 1012, '腐朽菌', '症狀：鳳凰木染病害；受害描述：老樹經多年的生長，多少會有木材腐朽的問題，主要發生的原因是樹皮遭受破壞而導致木質部的裸露，木材腐朽菌有機會接觸到木材並開始利用酵素，分解木材以供其生長。修剪，移植或枝條斷裂時皆會產生傷口，而使木質部裸露。 有些傷口會因樹皮的生長而自然癒合，但是一些無法癒合的傷口，使木質部裸露，容易成為木材腐朽菌棲息的場所，隨時間的進展腐朽部位會漸漸擴大，形成樹洞，樹洞又是許多昆蟲及小動物的棲息場所，在昆蟲及木材腐朽菌的協力下，腐朽速度會增加。木質部被過度蛀蝕腐朽時樹木的支撐力會越形薄弱，最後枝條或樹幹有掉落甚至於樹木本身有傾倒的危險。；確認方式：現地診察。', '此官方歷史案例含特定藥劑、濃度或施用方式，可能不符合目前核准用法，系統不直接回傳該舊處方。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-ae9323c57440423cf573c8bb');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (202, 1012, '褐根病', '症狀：全株乾枯無葉；確認方式：樣本檢驗。', '官方歷史案例建議：樣本檢驗為樹木褐根病危害，為避免容易造成公共危險，建議連根移除立地進行土壤燻蒸消毒。將受害植株的主根掘起並燒燬，無法完全掘出之受害細根，可施用尿素並最好覆蓋塑膠布2星期以上，尿素的用量約為每公頃700-1000公斤。此方法可以殺死土壤中細根的病原菌，尤其在鹼性土壤更有效。另外可以考慮使用燻蒸劑邁隆美公頃300-600公斤拌入土中加水後覆蓋塑膠布2星期以上，進行燻蒸。發病地區如不便將主根掘起且該地區具有灌溉系統，可進行1個月的浸水，以殺死存活於殘根的病原菌。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-856a5fe68da64cb0333d04bf');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (203, 1013, '樹木褐根病', '症狀：根部已出現菌絲面,一部份根已嚴重腐朽；確認方式：現地診察。', '官方歷史案例建議：現場勘查為樹木褐根病危害，為避免容易造成公共危險，建議連根移除立地進行土壤燻蒸消毒。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-9a1eba1e4f87aae3149beafb');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (204, 1017, '熱帶靈芝', '症狀：樹木木材腐朽，樹幹及樹基部腐朽中空。；確認方式：現地診察。', '官方歷史案例建議：去除靈芝並燒毀，加強養分水分管理，可以施用有機肥1次(每2~3年1次)。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-35372ed1495dbb041162a343');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (205, 1018, '褐根病', '症狀：大量落葉,葉子黃化,整株死亡；確認方式：現地診察。', '官方歷史案例建議：現場勘查為樹木褐根病危害，為避免容易造成公共危險，建議連根移除立地進行土壤燻蒸消毒。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-78ef4c6d9c756c99db498dca');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (206, 837, '松樹葉震病', '症狀：葉斑；確認方式：現地診察。', '官方歷史案例建議：如附頁。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-e050405f2a172fd8c142e534');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (207, 837, '流膠病', '症狀：發生流膠現象，懷疑是由松材線蟲引起或是細菌性潰瘍病；確認方式：現地診察。', '官方歷史案例建議：1.泵漫帢o病的枝條、樹幹應該予以修剪，並移除或燒毀，以避免成為傳染之來源。 2.注意修枝器具必須消毒後使用，患部可塗抹石灰硫磺合劑，防止遭受隨雨水傳播之孢子感染。 3.定期噴施殺菌劑，如鋅乃浦、鋅錳乃浦等，每二週一次，連續4-5次。防治措施應自幼株開始，可保護以後之健康。 4.對已罹病之樹幹或大枝幹，可用刀將樹皮刮掉，再用殺菌劑處理，以抑制病原菌之蔓延及產孢。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-7b9c6641e94b1769a1bf8fce');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (208, 837, '葉震病', '症狀：起初在針葉上形成許多黃色或黃褐色的小斑點，而後在病葉上形成一節節黃褐色至褐色的病斑，並有濃褐色之帶狀線，以後葉片逐漸變褐色至灰褐色枯死；確認方式：現地診察。', '官方歷史案例建議：現場勘查發現周圍地上有掉落枯萎葉子及松樹本上葉片上均有病原菌之子囊果，建議立即清除，疫區建議噴施波爾多劑。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-f4142e02f4fe072331431b4a');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (209, 837, '褐根病', '症狀：枝條枯黃(98/2/9北區研習講師判斷疑似褐根病危害)。；確認方式：樣本檢驗。', '官方歷史案例建議：樣本檢驗結果為樹木褐根病危害，為避免容易造成公共危險，建議連根移除立地進行土壤燻蒸消毒。方法如下： 1. 掘溝阻斷法：在健康樹與病樹間掘溝深約1公尺，並以強力膠布阻隔後回填土壤，以阻止病根與健康根的接觸傳染。 2. 將受害植株的主根掘起並燒毀。另外可以考慮使用燻蒸劑邁隆，每公頃300-600公斤拌入土中加水後覆蓋塑膠布2星期以上，進行燻蒸。 3. 發病地區如不便將主根掘起且該地區具有灌溉系統，可進行1個月的浸水，以殺死存活於殘根的病原菌。 提供您邁隆的廠商：嘉泰企業 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-398fcff2f8bdd2a1c05ca5d7');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (210, 1019, '疫病菌&腐黴菌', '症狀：全面枯死；確認方式：現地診察。', '此官方歷史案例含特定藥劑、濃度或施用方式，可能不符合目前核准用法，系統不直接回傳該舊處方。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-c6b659ef2f973602b068ee13');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (211, 1019, '褐根病', '症狀：葉片黃化枯萎；確認方式：現地診察。', '官方歷史案例建議：植株已枯死，建議砍除避免倒伏發生危險。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-46e792ea0b036863e436dbea');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (212, 1020, '枝枯病', '症狀：被害梢部及葉變褐色枯死，後期轉為灰褐色，在枯死枝條上生出許多粉紅色球形或半圓球形之小點，，導致黑褐色壞疽，嚴重時枝枯或地上部枯死；確認方式：現地診察。', '官方歷史案例建議：現場勘查發現周圍地上有掉落枯萎葉子及龍柏本上葉片上均有病原菌之子囊果，建議立即剪除發病枝，清除掉落之枯枝，並集中燒毀，可減輕病害之發生。如發病嚴重，可噴施殺菌劑以防治之。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-de8482c73f433ef7a6b2dff8');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (213, 1020, '枝枯病炭疽病', '症狀：局部枝枯導致葉枯；確認方式：現地診察。', '官方歷史案例建議：本病害是因修剪枝條導致弱病原菌自傷口感染，防治之建議： 1.避免在潮濕溫暖的季節進行修枝。 2.修枝前後使用殺菌劑保護，如免賴得、大生等殺菌劑。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-0ea47b37432c8d093393c0ae');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (214, 1020, '褐根病', '症狀：整株葉子黃化，根部已有菌絲面產生；確認方式：現地診察。', '官方歷史案例建議：為避免容易造成公共危險，建議連根移除立地進行土壤燻蒸消毒。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-b4c28067b25c2534cd35284f');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (215, 530, '褐根病', '症狀：枝葉稀疏、生長勢不佳、嚴重腐朽；確認方式：現地診察。', '官方歷史案例建議：經會勘發現，南瀛總爺藝文中心園區內之龍眼係罹患樹木褐根病。引起樹木褐根病之病原Phellinus noxius具傳染性，可藉根與根的接觸傳染。Phellinus noxius除了為病原菌、可使樹木染病、死亡外，也是一種木材腐朽菌，使罹病植株之木材腐朽、鬆軟、失去其物理結構。園區內染病之龍眼生長勢不佳、枝葉稀疏，且一側的根基部因病而嚴重腐朽、空洞。為了避免病株無欲警傾倒而造成人員傷亡、病情繼續蔓延至鄰近健康植株，建議將病株砍除，並進行土壤燻蒸處理。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-30fa3964a8a4ce5456964ad2');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (216, 1021, '樹木褐根病', '症狀：原本青翠健壯的樹木，突然間在一週左右整株死亡，葉子未掉。；確認方式：現地診察。', '官方歷史案例建議：申請人所寄標本病徵顯示，申請人所種植之龍眼樹係感染樹木褐根病。感染褐根病之樹木，樹根易腐朽、倒塌，為避免日後樹木倒塌壓傷人員或繼續感染周圍的樹種（褐根病可經由樹根接觸而感染健康的植株），須將感染死亡的樹木盡快移除，並將土內的病根、殘根清除乾淨，不可棄置原地(若殘根未撿除乾淨，燻蒸效果會較差，病原菌易殘存在較大的樹根內)；此外，再將病土作土壤燻蒸處理。由於燻蒸過後的土壤會變成「死土」（因燻蒸劑會將土壤中的微生物和蚯蚓等生物殺死），因此，燻蒸後需再添加有機肥以恢復土壤中的生物活性。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-e8b2c489b580eb564d469a29');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (217, 1021, '褐根病', '症狀：全株炸?>；確認方式：現地診察。', '此官方歷史案例含特定藥劑、濃度或施用方式，可能不符合目前核准用法，系統不直接回傳該舊處方。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-00c369a43c99e47eca55e597');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (218, 1022, '葉斑病', '- 葉片初期出現黃褐色至紫褐色之圓形或不規則形水浸狀小斑點。\n- 後期病斑逐漸擴大並互相融合，邊緣深褐色，中央呈灰白色，嚴重時導致早期枯黃落葉。\n- 高濕多雨環境下，病斑處表面可見細微黑色分生孢子器點狀物。', '1. 定期巡視並儘速剪除受害病葉，徹底清理地面落葉集中銷毀，阻斷感染源。\n2. 改善植株通風與日照條件，避免枝葉過密，澆水時儘量避免澆灌淋濕葉面。\n3. 發病初期可配合植物保護手冊，適度施用廣效保護型殺菌劑進行預防控制。', '農業部樹木病蟲害診斷案例', 'https://www.google.com/search?q=birch+leaf+spot', NULL);
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (220, 4, '黴菌腐爛', '- 西瓜果肉表面覆蓋大面積灰白色至淺綠色的絨毛狀黴菌菌落。\n- 果肉組織已明顯軟爛、分解，呈現濕潤黏稠狀。', '1. 立即丟棄受感染的西瓜，切勿食用或嘗試切除受損部分食用，以免攝入有害黴菌毒素。\n2. 徹底清潔任何與腐爛西瓜接觸過的刀具、砧板、檯面及儲存容器，使用肥皂水或稀釋漂白水消毒，防止黴菌孢子擴散。\n3. 檢查並改善西瓜的儲存環境，確保儲存在陰涼、乾燥且通風良好的地方，避免陽光直射和潮濕。\n4. 未來購買或儲存西瓜時，選擇外皮完整無損、無裂口或擦傷的果實，並儘早食用。', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-dis-220');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (221, 632, '灰黴病', '- 果實表面出現灰白色至灰褐色絨毛狀黴菌。\n- 受感染部位果肉軟化並腐爛。', '1. 立即移除並銷毀所有受感染的草莓，以防止病害擴散。\n2. 儲存時保持低溫（0-2°C）和適當的濕度（約90-95%），避免高濕環境。\n3. 確保草莓採收後盡快食用或冷藏，減少貯藏時間，降低病原發展機會。', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-dis-221');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (222, 821, '葉斑病', '- 葉片上出現許多不規則的紅褐色至深褐色斑點。\n- 斑點可能擴大並融合，形成較大的壞死區域。\n- 部分葉緣呈現焦枯或變色現象。', '1. 修剪並清除所有受感染的葉片及植物殘骸，特別是落葉，以減少病原菌的傳播。\n2. 改善植物周圍的通風，例如修剪過於密集的枝條，確保空氣流通。\n3. 避免傍晚或夜間對葉片進行澆水，盡量採用滴灌或底部澆水，以減少葉面濕潤時間。\n4. 若病害嚴重，可施用推薦的殺菌劑，如銅製劑、百克敏或代森錳鋅等，並務必按照產品說明和安全指示使用。', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-dis-222');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (223, 1023, '缺鐵症', '- 新生葉片呈現明顯的葉脈間黃化，而葉脈仍保持綠色。\n- 葉片整體顏色較為淡黃，生長勢減弱。', '1. 檢查土壤酸鹼度 (pH值)：扶桑適合微酸性至中性土壤 (pH 6.0-7.0)。若土壤過於鹼性，會導致鐵質難以吸收。可施用硫磺粉或酸性有機質肥料來調整土壤pH值。\n2. 補充螯合鐵肥：立即施用螯合鐵肥 (如EDTA鐵、DTPA鐵等)，可進行葉面噴施或土壤灌注，效果較快且穩定。\n3. 改善土壤通氣與排水：避免土壤長時間積水或過於密實，良好的土壤通氣有助於根部健康生長和養分吸收。', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-dis-223');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (224, 1024, '葉斑病', '- 葉片上出現不規則形狀的紅褐色至紫褐色斑點\n- 斑點散佈於葉片表面\n- 部分斑點擴大並融合，尤其是在葉緣附近', '1. 修剪並清除受感染的葉片及植株殘體，以減少病原殘存及傳播。\n2. 改善植株周圍的通風，確保葉片能迅速乾燥，降低病害發生條件。\n3. 避免傍晚澆水或使用噴灌，以減少葉面長時間濕潤。\n4. 嚴重情況下，可施用推薦的廣效性殺菌劑（如含代森錳鋅、百菌清或銅製劑的產品），並按照產品說明使用。', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-dis-224');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (225, 535, '黑星病 (Apple Scab)', '主要危害葉片和果實。葉面上出現淡黃褐色圓形斑點，後擴大並長出黑綠色至深褐色天鵝絨狀黴層，嚴重時果實龜裂畸形。', '1. 秋冬季清除落葉與病果並集中燒毀。\n2. 早春萌芽前噴灑石硫合劑或波爾多液。\n3. 發病初期選用待克利或賽普護汰寧等登記藥劑進行防治。', 'PlantVillage', NULL, NULL);
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (226, 535, '黑腐病 (Black Rot)', '侵害葉片、果實及枝幹。葉片形成「青蛙眼」狀同心輪紋病斑；果實形成暗褐色同心輪紋腐爛，其上密生小黑粒點。', '1. 修剪枯病枝並塗抹傷口保護劑。\n2. 落花後及時清理病僵果。\n3. 噴灑貝芬替或待克利等保護性殺菌劑。', 'PlantVillage', NULL, NULL);
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (227, 535, '銹病 (Cedar Apple Rust)', '葉片表面出現亮黃色至橘紅色圓形病斑，病斑周圍有紅暈；後期葉背隆起並產生毛狀銹孢子器，嚴重時提早落葉。', '1. 果園周圍避免種植檜柏等轉主寄主。\n2. 於展葉期至落花後噴灑三泰芬或腈菌唑等三唑類殺菌劑。\n3. 及早摘除初發病葉。', 'PlantVillage', NULL, NULL);
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (228, 525, '白粉病 (Powdery Mildew)', '嫩梢和葉片表面覆蓋一層白色粉狀黴層，受害葉片常捲曲、變厚且脆，嫩葉生長停滯，嚴重時提早落葉。', '1. 剪除受害嚴重的發病嫩梢與老葉。\n2. 保持樹冠內部通風透光。\n3. 發病初期可噴施硫磺膠體劑、亞托敏或三泰芬可濕性粉劑。', 'PlantVillage', NULL, NULL);
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (229, 7, '灰斑病 (Gray Leaf Spot)', '葉片上出現長矩形暗褐色至灰色病斑，病斑邊緣受平行葉脈限制成筆直條紋狀，濕度高時病斑兩面密生灰色黴層。', '1. 選用抗病品種並實行合理輪作。\n2. 收穫後徹底翻耕田土與清除病殘體。\n3. 發病初期噴施亞托敏、待克利或吡唑醚菌酯等殺菌劑。', 'PlantVillage', NULL, NULL);
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (230, 7, '銹病 (Common Rust)', '葉片兩面散生或聚生圓形至長橢圓形紅褐色或鐵銹色夏孢子堆，後期表皮破裂散出紅褐色粉末。', '1. 發病初期及早噴灑三泰芬（粉銹寧）或戊唑醇等藥劑。\n2. 避免田間種植過密，加強通風降濕。\n3. 增施磷鉀肥，提升植株抗病力。', 'PlantVillage', NULL, NULL);
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (231, 7, '煤紋病 (Northern Leaf Blight)', '葉片上出現大型梭形灰綠色至灰褐色斑塊，長度可達 5 至 10 公分，潮濕時病斑表面產生大量灰黑色黴狀物。', '1. 選用抗病雜交品種。\n2. 及時摘除下部老葉病葉，減少初次侵染源。\n3. 發病初期以得克利、待克利或代森錳鋅噴霧防治。', 'PlantVillage', NULL, NULL);
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (232, 560, '黑腐病 (Black Rot)', '葉片出現紅褐色圓形病斑，邊緣深褐色；果實受害先呈淡褐色軟腐，後迅速皺縮乾癟為堅硬黑褐色僵果，表面密生黑色小粒。', '1. 冬季徹底清園，刮除老皮並清除僵果枯葉。\n2. 開花前後及幼果期噴灑多菌靈、待克利或波爾多液。\n3. 套袋保護果穗，避免雨水飛濺傳播。', 'PlantVillage', NULL, NULL);
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (233, 560, '黑痘病 (Black Measles / Esca)', '葉片葉脈間黃化並壞死，呈現典型「虎斑紋」；果實表面出現小黑點，隨後果面局部凹陷乾枯變硬。', '1. 修剪時嚴禁帶菌工具，剪除病枝後立即塗抹殺菌保護劑。\n2. 萌芽前噴施石硫合劑清園。\n3. 改善土壤結構與排水，避免植株過度乾旱或積水應激。', 'PlantVillage', NULL, NULL);
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (234, 560, '褐斑病 (Leaf Blight)', '葉片出現大小不一的多角形或近圓形紅褐色至暗褐色病斑，葉背病斑對應處可見黑褐色絲絨狀黴層，多自下部老葉開始。', '1. 秋冬季清掃落葉並集中掩埋或燒毀。\n2. 生長期間及時綁蔓摘心，增強通風透光。\n3. 發病初期可選用待克利、撲滅寧或波爾多液進行防治。', 'PlantVillage', NULL, NULL);
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (235, 910, '黃龍病 (Citrus Greening)', '典型症狀為葉片「斑駁黃化」、葉脈木栓化或黃化，新梢發黃直立；果實變小、不對稱畸形且轉色不均（紅鼻子果），味酸味苦。', '1. 全面嚴格防治傳播媒介「柑橘木蝨」（使用益達胺或賽速安等藥劑）。\n2. 堅持種植無毒健康苗木。\n3. 田間一旦確認病株應立即整株挖除並石灰消毒，防範蔓延。', 'PlantVillage', NULL, NULL);
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (236, 527, '細菌性穿孔病 (Bacterial Spot)', '葉片最初出現水浸狀小斑點，後擴大為圓形至多角形紫褐色至黑褐色斑點，周圍具黃綠色暈圈，後期病斑乾枯脫落形成穿孔。', '1. 增施有機肥與鉀肥，增強樹勢。\n2. 發芽前噴灑波爾多液清園。\n3. 展葉後噴施農用鏈黴素、春雷黴素或氧氯化銅等銅製劑進行預防。', 'PlantVillage', NULL, NULL);
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (237, 1, '細菌性斑點病 (Bacterial Spot)', '葉片產生水浸狀小斑點，漸擴大成黃褐色近圓形病斑，中心淡褐色，邊緣深褐色微隆起，嚴重時落葉嚴重；果實表面產生粗糙隆起潰瘍斑。', '1. 實行 2-3 年輪作，播種前種子溫湯浸種消毒。\n2. 雨後注意排水，避免田間積水與高濕。\n3. 發病初期噴灑多寧、氫氧化銅或春雷黴素進行防治。', 'PlantVillage', NULL, NULL);
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (238, 386, '早疫病 (Early Blight)', '葉片出現深褐色圓形或橢圓形病斑，具明顯同心輪紋，潮濕時病斑上長出黑色黴層。多從植株下部老葉開始向上蔓延。', '1. 增施鉀肥與有機肥，防止植株早衰。\n2. 發病初期選用待克利、撲滅寧或百菌清進行葉面噴霧。\n3. 及時摘除底部枯老黃葉。', 'PlantVillage', NULL, NULL);
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (239, 386, '晚疫病 (Late Blight)', '葉尖或葉緣出現水浸狀暗綠色病斑，邊緣不明顯，濕度大時病斑邊緣生出一圈稀疏白黴；塊莖受害呈褐色凹陷腐爛。', '1. 嚴禁種植帶病種薯。\n2. 發現中心病株立即拔除。\n3. 流行前即早噴灑待克利、滅達樂、甲霜靈或波爾多液保護。', 'PlantVillage', NULL, NULL);
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (240, 648, '白粉病 (Powdery Mildew)', '初期葉面或葉背產生白色粉狀小黴斑，隨後蔓延覆蓋全葉，如撒上一層白粉，後期葉片黃化變脆、枯焦乾死。', '1. 注意通風透光，避免氮肥過量。\n2. 發病初期可用亞托敏、待克利、三泰芬或硫磺水懸劑進行均勻噴霧。\n3. 採收後清除病株殘體。', 'PlantVillage', NULL, NULL);
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (241, 632, '葉焦病 (Leaf Scorch)', '葉片表面散生無數紫褐色至紫紅色小圓斑，漸擴大融合成不規則暗紫色焦枯大斑，使整葉葉緣枯焦如火燒狀。', '1. 及時摘除病老葉集中深埋銷毀。\n2. 採用滴灌方式澆水，切忌噴灌漫灌。\n3. 發病初期噴施待克利、撲滅寧或百菌清保護葉片。', 'PlantVillage', NULL, NULL);
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (242, 639, '細菌性斑點病 (Bacterial Spot)', '葉片出現水浸狀暗綠色小斑點，漸轉為黑褐色稍凹陷斑點，外圍有黃色暈圈；果實表面形成火山口狀微隆起小黑點。', '1. 種子消毒處理。\n2. 發病初期噴灑氫氧化銅、鏈黴素或克無菌等銅製劑或抗生素。\n3. 避免在露水未乾前進行田間整枝作業。', 'PlantVillage', NULL, NULL);
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (243, 639, '葉黴病 (Leaf Mold)', '主要危害葉片，葉面初現不規則淡黃色褪綠斑，葉背相應部位長出初為白色、後漸轉為黃褐至黑褐色天鵝絨狀濃密黴層。', '1. 加強溫室通風排濕，控制相對濕度在 80% 以下。\n2. 發病初期可選用多菌靈、亞托敏或待克利噴灑。\n3. 及時摘除病葉改善通風。', 'PlantVillage', NULL, NULL);
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (244, 639, '斑枯病 (Septoria Leaf Spot)', '葉片產生直徑約 2-3 毫米小圓斑，邊緣暗褐色，中央灰白色凹陷，病斑上散生許多針頭大小黑色小粒點（分生孢子器）。', '1. 輪作換茬，清除田間病殘體。\n2. 發病初期噴施百菌清、待克利或代森錳鋅。\n3. 適當提早整枝打杈，改善田間通風。', 'PlantVillage', NULL, NULL);
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (245, 639, '靶斑病 (Target Spot)', '葉片出現圓形至不規則褐色壞死斑，具明顯黃色暈圈與同心靶環狀紋路，病斑脆裂易脫落穿孔。', '1. 注意田間排濕通風。\n2. 噴灑待克利、嘧菌酯或苯醚甲環唑進行保護與治療。\n3. 及時清除發病下位葉。', 'PlantVillage', NULL, NULL);
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (246, 639, '黃化捲葉病毒病 (Tomato Yellow Leaf Curl Virus)', '植株矮縮，上部葉片明顯縮小、向上捲曲、葉緣褪綠黃化變厚變脆，開花結果稀少，果實發育不良。', '1. 嚴防主要傳播媒介「銀葉粉蝨」（使用防蟲網、黃板及專用藥劑防治）。\n2. 選用抗病毒病（TY）品種。\n3. 發病初期拔除重病株並帶離田區銷毀。', 'PlantVillage', NULL, NULL);
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (247, 639, '嵌紋病毒病 (Tomato Mosaic Virus)', '葉片出現濃淡不均的黃綠相間斑駁或嵌紋，葉片凹凸不平、扭曲變形呈蕨葉狀，植株生長停滯。', '1. 整枝抹芽前先消毒雙手與剪刀，避免汁液接觸傳染。\n2. 及時防除蚜蟲等刺吸式害蟲。\n3. 播種前磷酸三鈉溶液浸種消毒。', 'PlantVillage', NULL, NULL);
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (248, 932, '葉片黃化 (營養缺乏)', '- 葉片普遍變淺或呈現黃綠色，嚴重時整片葉片均勻發黃。\n- 黃化可能從老葉或新葉開始，葉脈間出現黃化而葉脈仍保持綠色（視缺乏元素而異）。\n- 植株生長勢減弱，葉片可能變小、變薄，或提早落葉。', '1. 進行土壤檢測，以確定土壤的pH值和具體缺乏的營養元素。\n2. 根據土壤檢測結果，選用並施用含有缺乏養分（如氮、鐵、鎂、鋅）的均衡肥料或專用肥料。\n3. 調整土壤pH值至檸檬適宜的微酸性範圍（pH 5.5-6.5），以促進養分吸收。\n4. 改善土壤排水與通氣，避免土壤過濕或積水，確保根系健康吸收養分。\n5. 在快速需要補充微量元素時，可考慮葉面施肥作為輔助措施。', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-dis-248');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (249, 1026, '葉斑病', '- 葉片表面有散佈的圓形至不規則形狀紅褐色至深褐色斑點。\n- 部分斑點融合形成較大的壞死區域，尤其在葉緣。\n- 葉片組織在斑點處可能出現枯萎或凹陷。', '1. 修剪並清除所有受感染的葉片及掉落的枯葉，妥善銷毀以減少病原體傳播。\n2. 改善植株周圍通風，適度修剪樹冠，確保葉片間空氣流通，降低濕度。\n3. 避免傍晚澆水，減少葉片夜間保持濕潤的時間，降低真菌感染風險。\n4. 在嚴重感染時，可考慮施用標示可用於防治葉斑病的合適殺菌劑，並遵循產品說明操作。', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-dis-249');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (250, 932, '缺鎂症', '- 葉片呈現普遍黃化，特別是老葉。\n- 葉脈間區域變黃，部分葉緣及斑塊帶有紅褐色。\n- 果實外觀飽滿，表皮健康無明顯病斑。', '1. 進行土壤及葉片檢測，確認土壤pH值和具體缺乏的營養元素。\n2. 根據檢測結果，補充含鎂肥料，可選用硫酸鎂進行葉面噴施或土壤施用。\n3. 確保土壤排水良好且適當灌溉，避免過濕或過乾，並提供均衡的複合肥料。', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-dis-250');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (251, 1027, '葉斑病', '- 葉片表面散佈不規則的紅褐色至深褐色斑點。\n- 部分斑點可能擴大或融合成較大的病斑，邊緣不清晰。\n- 葉片邊緣可見受損及焦枯現象，影響光合作用。', '1. 定期修剪並清除所有受感染的葉片及落葉，避免病原體累積與傳播，並妥善銷毀（例如焚燒或深埋）。\n2. 改善植株周圍的通風環境，修剪過於密集的枝條，以減少葉面潮濕時間，抑制病菌生長。\n3. 避免高濕環境，澆水時盡量避免直接淋濕葉片，建議在清晨澆水，讓葉片有足夠時間在白天乾燥。\n4. 若病害情況嚴重，可考慮選用登記推薦的廣效性殺菌劑進行防治，並務必遵循產品說明安全使用。', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-dis-251');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (252, 527, '細菌性穿孔病', '- 【病徵特徵】：葉片最初出現水浸狀小斑點，後擴大為圓形至多角形紫褐色至黑褐色斑點，周圍具黃綠色暈圈，後期病斑乾枯脫落形成穿孔。\n- 【輕度初期】：若僅零星 1-2 片葉片或葉緣出現小斑點，其餘植株鮮綠健壯。\n- 【重度擴散】：若多數葉片出現大面積輪紋、壞疽枯萎或蔓延至莖桿。', '1. 【初期輕微處置】：及早剪除少量發病葉片並妥善丟棄；維持充足日照並改善通風，澆水時避免噴濕葉面，無須施藥即可自然控制。\n2. 【中重度擴散處置】：徹底清除嚴重病葉並清理地面落葉；1. 增施有機肥與鉀肥，增強樹勢。\n2. 發芽前噴灑波爾多液清園。\n3. 展葉後噴施農用鏈黴素、春雷黴素或氧氯化銅等銅製劑進行預防。\n3. 【環境防護管理】：適當拉開植株間距降低濕度，發病期暫停施用高氮肥料，保持盆土透氣瀝水避免病菌滋生。', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-dis-252');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (253, 632, '葉焦病', '- 【病徵特徵】：葉片表面散生無數紫褐色至紫紅色小圓斑，漸擴大融合成不規則暗紫色焦枯大斑，使整葉葉緣枯焦如火燒狀。\n- 【輕度初期】：若僅零星 1-2 片葉片或葉緣出現小斑點，其餘植株鮮綠健壯。\n- 【重度擴散】：若多數葉片出現大面積輪紋、壞疽枯萎或蔓延至莖桿。', '1. 【初期輕微處置】：及早剪除少量發病葉片並妥善丟棄；維持充足日照並改善通風，澆水時避免噴濕葉面，無須施藥即可自然控制。\n2. 【中重度擴散處置】：徹底清除嚴重病葉並清理地面落葉；1. 及時摘除病老葉集中深埋銷毀。\n2. 採用滴灌方式澆水，切忌噴灌漫灌。\n3. 發病初期噴施待克利、撲滅寧或百菌清保護葉片。\n3. 【環境防護管理】：適當拉開植株間距降低濕度，發病期暫停施用高氮肥料，保持盆土透氣瀝水避免病菌滋生。', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-dis-253');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (254, 1024, '榛樹褐斑病', '- 葉片上出現散佈的紅褐色至深褐色斑點。\n- 斑點形狀多變，從不規則到近圓形，部分斑點有相互融合形成較大壞死區的趨勢。\n- 葉緣處也觀察到斑點及組織壞死現象。', '1. 收集並銷毀所有受感染的落葉及枝條，以減少病原菌的越冬來源。\n2. 改善植株周圍的通風，例如適度修剪過於茂密的枝葉，避免葉片長時間保持濕潤。\n3. 在高濕度或病害易發時期，可考慮施用核准的銅基或廣效性殺菌劑進行預防或治療，務必遵循產品說明。', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-dis-254');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (255, 932, '營養缺乏', '- 檸檬果實呈橢圓形，表面有粗糙顆粒狀表皮，成熟時為黃色。\n- 葉片呈現普遍性黃化及部分褐斑，特別是老葉部分，顯示營養不良跡象。\n- 葉片未見明顯的特定病害斑點或蟲害痕跡。', '1. 進行土壤及葉片分析，以確定確切的營養缺乏類型（例如鎂、氮、鉀或其他微量元素）。\n2. 根據檢測結果，施用適量且平衡的肥料，針對性補充缺乏的養分。\n3. 確保提供適當的水分管理，避免土壤過乾或過濕，並改善土壤排水與通氣性。', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-dis-255');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (256, 1028, '葉斑病', '- 葉片表面廣泛分布紅褐色至紫黑色之圓形及不規則壞死病斑，葉緣部位病斑已有擴大融合趨勢，顯示病勢處於活躍發展期。\n- 病斑阻礙葉片正常光合作用，若未及時控制將引發大量落葉、新梢生長受阻，雨水飛濺更會加速病原菌擴散至其他健康葉片與果實。', '1. 病部修剪清園：剪除受害病葉與地面落葉並銷毀，切勿堆積於基部，阻斷二次感染源。\n2. 加強通風控水：適度疏枝改善通風採光，採根部澆水避免噴濕葉面，抑制孢子萌發。\n3. 登記藥劑防治：發病初期依規範噴施推薦殺菌劑（如銅劑保護劑或三唑類），輪替用藥避免抗藥性。', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-dis-256');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (257, 901, '缺鐵症', '- 頂端嫩葉失綠：新葉呈現典型脈間黃化，主脈維持深綠，為鐵移動性差之生理特徵。\n- 生長受阻風險：若持續缺鐵將引發葉緣焦枯，光合作用下降並影響花芽分化。', '1. 應急葉面補鐵：以水溶性螯合鐵（EDTA-Fe，稀釋 1000-1500 倍）於清晨均勻噴施葉面，每 7-10 天一次，連續 2-3 次改善新葉失綠。\n2. 調節土壤酸鹼：介質維持微酸性（pH 6.0-6.5）。若土壤偏鹼易阻礙鐵吸收，可添加酸性泥炭土或腐植酸微調。\n3. 控水與平衡施肥：避免盆土積水爛根，並暫停高磷肥料避免拮抗；若有蟲害請依農業部核准藥劑單獨施用，勿任意混藥。', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-dis-257');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (258, 4, '果腐病', '- 果肉組織已呈嚴重水浸狀潰爛並液化，表面密生青綠色、灰黑色與白色之複合黴菌菌絲及孢子，組織完全崩解，已喪失食用與商品價值。\n- 腐敗組織釋放大量真菌孢子與汁液，極易藉由接觸、氣流或害蟲媒介迅速擴散，造成田間相鄰果實或貯藏庫其他瓜果交叉感染。', '1. 徹底清除病原：立即將罹病果實裝袋密封帶離田區銷毀，作業工具徹底消毒，阻斷病原傳播。\n2. 改善排水通風：落實作畦排水，果實底部鋪設果墊避免直接觸土，搬運輕拿輕放避免傷口。\n3. 合理藥劑防治：雨季前後輪替噴施瓜類核准保護藥劑（如銅劑、待克利），嚴守安全採收期。', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-dis-258');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (259, 932, '炭疽病', '- 葉片邊緣及葉尖呈現黃化及褐色壞疽斑塊，易導致提早落葉並削弱光合作用與植株樹勢。\n- 病原菌易於枯枝殘葉殘留，遇潮濕多雨時隨水滴飛濺擴散，增加果實感染黑斑及腐爛風險。', '1. 清除病源：剪除枯枝、病葉及落果並移出果園集中燒毀或深埋，減少炭疽病菌源殘留與傳播。\n2. 藥劑防治：發病初期輪流噴施23%亞托敏水懸劑1000倍或80%鋅錳乃浦可濕性粉劑500倍液全株防治。\n3. 樹勢管理：修剪內部過密枝條以改善通風採光，雨季前補施磷鉀肥，避免偏施氮肥以強化組織抗病力。', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-dis-259');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (260, NULL, '炭疽病', '- 典型病徵：葉面出現【炭疽病】局部色斑、褪綠或水浸狀壞死，請注意受害程度。\n- 擴散風險：高溫多濕或通風不良時易向相鄰健康組織蔓延，需即時採取防護。', '1. 病斑修剪隔離：立即剪除發病葉片並集中銷毀，修剪工具消毒，阻斷病原二度感染。\n2. 通風控水管理：維持良好通風採光，採盆土注水避免噴濕葉面，發病期間暫停施用氮肥。\n3. 推薦保護資材：參照【芒果】植保手冊，於發病初期施用登記核准藥劑或保護型殺菌劑。', '農業部動植物防疫檢疫署 (APHIA) 與 Gemini 多模態視覺病理知識庫', 'https://www.aphia.gov.tw', 'aphia-gemini-芒果-炭疽病');
INSERT INTO `disease` (`disease_id`, `crop_id`, `disease_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (262, 14, '白化症', '白化症之典型病徵（由農業專家主動學習覆核登錄）。', '1. 請依照專家建議之對應處方進行植株照護。\n2. 維持良好通風與田間水分管理。', '專家主動學習覆核新定名', NULL, NULL);
INSERT INTO `pests` (`pest_id`, `crop_id`, `pest_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (1, 2, '蟲害', '葉片出現明顯孔洞與邊緣褐化，疑遭蟲害。', '仔細檢查葉背及土壤，手動移除害蟲或使用天然驅蟲劑。', '農業部動植物防疫檢疫署害蟲防治指引', 'https://www.aphia.gov.tw', 'aphia-pest-1');
INSERT INTO `pests` (`pest_id`, `crop_id`, `pest_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (2, 2, '薊馬', '葉面有微小白斑點，可能為初期刺吸式害蟲。', '密切觀察，若蟲害加劇可考慮使用生物防治或苦楝油。', '農業部動植物防疫檢疫署害蟲防治指引', 'https://www.aphia.gov.tw', 'aphia-pest-2');
INSERT INTO `pests` (`pest_id`, `crop_id`, `pest_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (3, 639, '銀葉粉蝨 (Whitefly)', '成蟲和若蟲聚集在葉片背面吸食汁液，導致葉片黃化、捲曲，並分泌蜜露誘發煤煙病。同時也是傳播病毒病的主要媒介。', '可利用黃色黏蟲板誘殺成蟲。藥劑防治可選用 10% 吡蟲啉可濕性粉劑 1500 倍液，或 25% 噻蟲嗪水分散粒劑 3000 倍液。', '農業部動植物防疫檢疫署害蟲防治指引', 'https://www.aphia.gov.tw', 'aphia-pest-3');
INSERT INTO `pests` (`pest_id`, `crop_id`, `pest_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (4, 639, '棉鈴蟲 (Bollworm)', '幼蟲會鑽入番茄果實內部取食，造成果實腐爛脫落。一個幼蟲可危害多個果實，果實表面可見蟲孔及新鮮蟲糞。', '在幼蟲孵化初期，尚未鑽入果實前噴藥最有效。可使用甲維鹽、氯蟲苯甲醯胺等藥劑。也可利用黑光燈誘殺成蛾。', '農業部動植物防疫檢疫署害蟲防治指引', 'https://www.aphia.gov.tw', 'aphia-pest-4');
INSERT INTO `pests` (`pest_id`, `crop_id`, `pest_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (5, 639, '蚜蟲 (Aphid)', '群聚於嫩葉、嫩莖和花蕾上吸食汁液，造成植株生長不良、葉片捲曲變形。其排泄物會誘發煤煙病，並傳播多種病毒。', '發生量少時可手動清除或用水沖洗。天敵（如瓢蟲、草蛉）可有效控制。藥劑可選用吡蟲啉、啶蟲脒等，注意保護天敵。', '農業部動植物防疫檢疫署害蟲防治指引', 'https://www.aphia.gov.tw', 'aphia-pest-5');
INSERT INTO `pests` (`pest_id`, `crop_id`, `pest_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (6, 850, '咖啡果小蠹', '農業部診斷圖鑑記錄：咖啡果小蠹可危害亞歷山大椰子的果實。 學名：Hypothenemus hampei。', '官方資料未提供可直接套用的處置方式。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部重要農業害蟲診斷圖鑑', 'https://data.moa.gov.tw/Service/OpenData/AgriculturalPestsDetail.aspx?Tracecode=diag13086001', 'diag13086001');
INSERT INTO `pests` (`pest_id`, `crop_id`, `pest_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (7, 691, '太平洋臀紋粉介殼蟲', '農業部診斷圖鑑記錄：太平洋臀紋粉介殼蟲可危害仙丹花的莖部。 學名：Planococcus minor。', '官方資料未提供可直接套用的處置方式。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部重要農業害蟲診斷圖鑑', 'https://data.moa.gov.tw/Service/OpenData/AgriculturalPestsDetail.aspx?Tracecode=diag13090001', 'diag13090001');
INSERT INTO `pests` (`pest_id`, `crop_id`, `pest_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (8, 195, '黃綠綿介殼蟲', '農業部診斷圖鑑記錄：黃綠綿介殼蟲可危害仙草的莖部、葉片。 學名：Pulvinaria psidii。', '官方資料未提供可直接套用的處置方式。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部重要農業害蟲診斷圖鑑', 'https://data.moa.gov.tw/Service/OpenData/AgriculturalPestsDetail.aspx?Tracecode=diag13157001', 'diag13157001');
INSERT INTO `pests` (`pest_id`, `crop_id`, `pest_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (9, 856, '木瓜秀粉介殼蟲', '農業部診斷圖鑑記錄：木瓜秀粉介殼蟲可危害加蜜蛋黃果的莖部、葉片、果實。 學名：Paracoccus marginatus。', '官方資料未提供可直接套用的處置方式。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部重要農業害蟲診斷圖鑑', 'https://data.moa.gov.tw/Service/OpenData/AgriculturalPestsDetail.aspx?Tracecode=diag13082001', 'diag13082001');
INSERT INTO `pests` (`pest_id`, `crop_id`, `pest_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (10, 857, '金花蟲', '農業部診斷圖鑑記錄：金花蟲可危害十字花科的葉片。 學名：Chrysomelidae。', '官方資料未提供可直接套用的處置方式。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部重要農業害蟲診斷圖鑑', 'https://data.moa.gov.tw/Service/OpenData/AgriculturalPestsDetail.aspx?Tracecode=diag13001001', 'diag13001001');
INSERT INTO `pests` (`pest_id`, `crop_id`, `pest_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (11, 648, '椿象', '農業部診斷圖鑑記錄：椿象可危害南瓜的植株。 學名：Pentatomomorpha。 補充：Y', '官方資料未提供可直接套用的處置方式。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部重要農業害蟲診斷圖鑑', 'https://data.moa.gov.tw/Service/OpenData/AgriculturalPestsDetail.aspx?Tracecode=diag13032001', 'diag13032001');
INSERT INTO `pests` (`pest_id`, `crop_id`, `pest_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (12, 520, '橘球粉介殼蟲', '農業部診斷圖鑑記錄：橘球粉介殼蟲可危害印度棗的葉片。 學名：Nipaecoccus viridis。', '官方資料未提供可直接套用的處置方式。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部重要農業害蟲診斷圖鑑', 'https://data.moa.gov.tw/Service/OpenData/AgriculturalPestsDetail.aspx?Tracecode=diag13118001', 'diag13118001');
INSERT INTO `pests` (`pest_id`, `crop_id`, `pest_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (13, 865, '長尾粉介殼蟲', '農業部診斷圖鑑記錄：長尾粉介殼蟲可危害台灣山蘇花的葉片。 學名：Pseudococcus longispinus。', '官方資料未提供可直接套用的處置方式。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部重要農業害蟲診斷圖鑑', 'https://data.moa.gov.tw/Service/OpenData/AgriculturalPestsDetail.aspx?Tracecode=diag13081001', 'diag13081001');
