INSERT INTO `pests` (`pest_id`, `crop_id`, `pest_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (148, 848, '松材線虫', '症狀：疑遭松材線蟲危害；確認方式：現地診察。', '官方歷史案例建議：1.可寄送樣本我們可以協助進行分離鑑定。 2.若出現病徵，建議立即砍除病對受害木進行銷毀工作避免病害快速傳播。可參考松材線蟲防治手冊http://oldpage.tfri.gov.tw/book/nematode/nema-f9.htm。 3.尚未受到危害的樹木如果有保護的價值可以參考植物保護手冊有關松線虫的登記用藥http://www.tactri.gov.tw/htdocs/ppmtable/fod-06.pdf。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-ac4cb1422b376e520d81fd1a');
