INSERT INTO `pests` (`pest_id`, `crop_id`, `pest_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (154, 859, '天牛', '症狀：本校南洋杉日前觀察樹幹本體有多處蟲蛀痕跡，距離根部上方樹幹約30公分處有多處洞口，探查洞口深達15cm，且洞口會流出大量汁液。(附圖)南洋杉樹葉也日漸枯黃；確認方式：樣本檢驗。', '此官方歷史案例含特定藥劑、濃度或施用方式，可能不符合目前核准用法，系統不直接回傳該舊處方。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-b12caf580c2b13d67f6efc3d');
INSERT INTO `pests` (`pest_id`, `crop_id`, `pest_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (155, 862, '夜蛾', '症狀：葉片有綠色毛蟲危害；確認方式：樣本檢驗。', '官方歷史案例建議：由於該害蟲危害已結束，就郵寄來的幼蟲化蛹情形判斷，吐絲量很少，有可能是在地表結繭，建議將落葉層清除銷毀，即可消除大部分的蟲蛹。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-f0109c1bbd38d59317fb7903');
