INSERT INTO `pests` (`pest_id`, `crop_id`, `pest_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (158, 867, '小蠹蟲', '症狀：不名害蟲蛀食樹幹致生枯萎乾死；確認方式：樣本檢驗。', '官方歷史案例建議：蠹蟲主要以樹幹內壞死組織為食，屬於腐生性。一般樹木生長過程中，或多或少會有這一類的昆蟲取食，在正常生長的健康植株，並不受其影響，不需任何防治處理。乾死株反倒是與櫸木的生育地有關，土壤排水要良好，不可以積水，以含有部份砂質或石礫的土壤為佳，並注意避免水份不足的情形發生，如此樹木才可正常生長。由於櫸木會隨著樹木生長，對於生育地的條件要求愈高，因此斜坡上的該案樹木，很有可能因水份不足導致乾枯，所以可以加強水份灌溉。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-085beb883fae86e65bef8fdf');
INSERT INTO `pests` (`pest_id`, `crop_id`, `pest_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (159, 867, '螟蛾', '症狀：全株枯死；確認方式：樣本檢驗。', '此官方歷史案例含特定藥劑、濃度或施用方式，可能不符合目前核准用法，系統不直接回傳該舊處方。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-6b4a7e62432ccd4cdc1f6cae');
INSERT INTO `pests` (`pest_id`, `crop_id`, `pest_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (160, 259, '蝗蟲、天牛、潛葉蛾', '症狀：嫩芽乾枯 莖部發現蟲；確認方式：樣本檢驗。', '此官方歷史案例含特定藥劑、濃度或施用方式，可能不符合目前核准用法，系統不直接回傳該舊處方。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-5e7ef2d71332f1056912b34a');
INSERT INTO `pests` (`pest_id`, `crop_id`, `pest_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (161, 876, '刺桐釉小蜂', '症狀：蟲癭；確認方式：現地診察。', '官方歷史案例建議：未嚴重發病，蟲不多，持續觀察。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-ee97622c732264ae0f02178e');
INSERT INTO `pests` (`pest_id`, `crop_id`, `pest_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (162, 878, '白蟻、生理性缺水', '症狀：樹幹變黃後會爆裂；確認方式：現地診察。', '官方歷史案例建議：我們分幾個問題處理，一是有白蟻的部份其實並不嚴重只需使用強力水柱直接沖洗掉白蟻危害的部位(白蟻窩)及在樹幹基部灌水即可，二是樹皮剝離的問題可能是生理性缺水(機會較大)或真菌感染所造成，建議進行修除有這樣現象的枝條即可，其他樹木看起來生長很正常(還在冒新芽)沒有問題，由於樹木種在住宅區內所以樹幹基部周圍一定有水泥地或柏油路面覆蓋，這會限制樹木的生長，當樹木長到一定程度就會有一些生理反應，在此建議樹木應每二年施肥一次並修除枯萎枝條以維樹木正常生長。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-97e4019ee30c40e078bac590');
INSERT INTO `pests` (`pest_id`, `crop_id`, `pest_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (163, 883, '竹涓夜蛾', '症狀：落葉；確認方式：現地診察。', '官方歷史案例建議：以南投49號縣道為主，共勘查三處(GPS site 788m 219969 2621173，867m 221623 2620883，900m 221897 2620775)，皆未發現竹涓夜蛾幼蟲有繼續危害的跡象，只有在一處觀察到羽化成功後的空蛹殼，孟宗竹生長部份，已經開始萌發新葉。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-7cfae898b0c05d74fb1b3d65');
INSERT INTO `pests` (`pest_id`, `crop_id`, `pest_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (164, 888, '樟蝙蝠蛾', '症狀：根基部遭受蟲體取食而環剝；受害描述：成蟲產卵在根際，幼蟲向上蠹蝕樹幹。根基部遭受蟲體取食而環剝；確認方式：現地診察。', '官方歷史案例建議：1.冬季剪枝時應剪去被害枝，並予以燒燬。 2.受害蔓莖可以鐵絲穿入被害孔道，或用棉花沾殺蟲劑塞入被害孔內，均可殺死幼蟲。 3.清理果園，剷除雜草及中間寄主。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-527d8a88bcc7676302ffad6e');
INSERT INTO `pests` (`pest_id`, `crop_id`, `pest_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (165, 888, '蝙蝠蛾', '症狀：根基部遭受蟲體取食而環剝；確認方式：現地診察。', '官方歷史案例建議：現場勘查發現為蝙蝠蛾危害。 1.冬季剪枝時應剪去被害枝，並予以燒燬。 2.受害蔓莖可以鐵絲穿入被害孔道，或用棉花沾殺蟲劑塞入被害孔內，均可殺死幼蟲。 3.清理果園，剷除雜草及中間寄主。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-bf2209747b3b3b2b2b41a078');
INSERT INTO `pests` (`pest_id`, `crop_id`, `pest_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (166, 686, '粉介殼蟲 煤灰病', '症狀：枝乾掉、葉掉完；確認方式：樣本檢驗。', '此官方歷史案例含特定藥劑、濃度或施用方式，可能不符合目前核准用法，系統不直接回傳該舊處方。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-786f0ba43fbe64a498db18b8');
INSERT INTO `pests` (`pest_id`, `crop_id`, `pest_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (167, 721, '介殼蟲', '症狀：末梢樹葉部分枯黃 枝葉略呈黑褐 末端樹葉出汁低到地上引來蒼蠅；確認方式：樣本檢驗。', '此官方歷史案例含特定藥劑、濃度或施用方式，可能不符合目前核准用法，系統不直接回傳該舊處方。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-1dee3e0736d46ef5adffae76');
INSERT INTO `pests` (`pest_id`, `crop_id`, `pest_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (168, 891, '蘇鐵白輪盾蚧', '症狀：枝葉上遭受白色蟲子危害；確認方式：樣本檢驗。', '此官方歷史案例含特定藥劑、濃度或施用方式，可能不符合目前核准用法，系統不直接回傳該舊處方。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-b3198b45b5ff8e83a175860d');
INSERT INTO `pests` (`pest_id`, `crop_id`, `pest_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (169, 896, '天牛', '症狀：樹基部有天牛之排遺；受害描述：受害徵兆為天牛危害但未見天牛無法鑑定天牛種類常見的有星天牛故參齒傢鰬P天牛之資料進行防治，資料如下：本蟲一年一世代，成蟲一般於每年四至七月出現，多在距地面約0.5公尺處以口器咬破樹皮產卵於裂縫內，每處一粒，每隻雌蟲可產卵70至80粒。孵化後幼蟲先繞皮層內側盤食，後蛀食木質部，造成若干隧道。被害株基部常可發現由隧道口排出之木屑及蟲糞，嚴重被害葉片黃化凋落，樹勢衰弱，最後炸鉿漱`。；確認方式：現地診察。', '此官方歷史案例含特定藥劑、濃度或施用方式，可能不符合目前核准用法，系統不直接回傳該舊處方。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-61169b4bed0b945ae5cd33c4');
INSERT INTO `pests` (`pest_id`, `crop_id`, `pest_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (170, 896, '月橘盾介殼蟲', '症狀：樹勢生長不佳。；確認方式：現地診察。', '官方歷史案例建議：已於現勘中回覆申請人。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-bcf551049970aec540664ed1');
INSERT INTO `pests` (`pest_id`, `crop_id`, `pest_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (171, 899, '白蟻', '症狀：白蟻發生；確認方式：現地診察。', '官方歷史案例建議：天氣常時間乾旱，樹木遭受白蟻為害時，建議使用灌水方式來防治。水柱沖洗樹幹受害部位，另外，用徒手工具將樹基部周圍挖出溝渠後，再大量灌水淹沒蟻窩，每日二次，持續1-2週。若還有白蟻出現才使用白蟻藥，灌注於樹基部內，此藥毒性甚強使用要非常小心，避免人員靠近。但樹幹若柱蝕出現中空現象，恐有傾倒之危險，建議砍除以維安全。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-a5bbad5beb458f51ff11beb7');
INSERT INTO `pests` (`pest_id`, `crop_id`, `pest_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (172, 904, '軍配蟲', '症狀：根基部遭受蟲體取食而環剝；確認方式：現地診察。', '此官方歷史案例含特定藥劑、濃度或施用方式，可能不符合目前核准用法，系統不直接回傳該舊處方。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-bf39ede25fd548905f420058');
INSERT INTO `pests` (`pest_id`, `crop_id`, `pest_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (173, 905, '松材線蟲', '症狀：底部枝條、葉分枝逐漸往上乾枯；確認方式：現地診察。', '此官方歷史案例含特定藥劑、濃度或施用方式，可能不符合目前核准用法，系統不直接回傳該舊處方。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-cf5126878f72d6c85c5a0cab');
INSERT INTO `pests` (`pest_id`, `crop_id`, `pest_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (174, 905, '松線虫', '症狀：疑似松材線蟲危害；確認方式：現地診察。', '官方歷史案例建議：1.可寄送樣本我們可以協助進行分離鑑定。 2.若出現病徵，建議立即砍除病對受害木進行銷毀工作避免病害快速傳播。可參考松材線蟲防治手冊http://oldpage.tfri.gov.tw/book/nematode/nema-f9.htm。 3.尚未受到危害的樹木如果有保護的價值可以參考植物保護手冊有關松線虫的登記用藥http://www.tactri.gov.tw/htdocs/ppmtable/fod-06.pdf。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-072b487b2f43016e05586968');
INSERT INTO `pests` (`pest_id`, `crop_id`, `pest_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (175, 905, '白蟻', '症狀：樹幹從根部開始長白蟻侵蝕樹幹；確認方式：現地診察。', '官方歷史案例建議：可分兩部分處理。土壤部份，較嚴重危害的樹基部先用水泥推砌成一土圈後，已灌水方式灌於樹基部，每株大約需50公升，每天一次，連續兩週。樹幹部份則以水柱直接沖洗白蟻窩，保持樹幹乾淨不要再築巢即可。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-244cd73acc355dcb6e60a585');
INSERT INTO `pests` (`pest_id`, `crop_id`, `pest_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (176, 906, '松材線蟲', '症狀：針葉轉赤褐色、全株枯死；確認方式：現地診察。', '官方歷史案例建議：經會勘發現校區內松樹係遭受松材線蟲感染致死，建議將病株砍除並銷毀，健康株則盡快進行防治工作以免疫情擴大。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-13717bb845e50e1a855a1211');
INSERT INTO `pests` (`pest_id`, `crop_id`, `pest_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (177, 906, '萎凋病', '症狀：全株泵?>；確認方式：現地診察。', '此官方歷史案例含特定藥劑、濃度或施用方式，可能不符合目前核准用法，系統不直接回傳該舊處方。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-501f904d662184d254e236fd');
INSERT INTO `pests` (`pest_id`, `crop_id`, `pest_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (178, 908, '白蟻', '症狀：樹幹從根部開始長白蟻侵蝕樹幹；確認方式：現地診察。', '官方歷史案例建議：可分兩部分處理。土壤部份，較嚴重危害的樹基部先用水泥推砌成一土圈後，已灌水方式灌於樹基部，每株大約需50公升，每天一次，連續兩週。樹幹部份則以水柱直接沖洗白蟻窩，保持樹幹乾淨不要再築巢即可。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-32d79930da781ac8b9d296b4');
INSERT INTO `pests` (`pest_id`, `crop_id`, `pest_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (179, 913, '桃蚜', '症狀：桃樹上面有上百隻不知是蝴蝶或蛾類.. 葉表面上有白粉；確認方式：現地診察。', '此官方歷史案例含特定藥劑、濃度或施用方式，可能不符合目前核准用法，系統不直接回傳該舊處方。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-45f3829a99187d30e91c9d99');
