INSERT INTO `pests` (`pest_id`, `crop_id`, `pest_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (181, 514, '椰子大象鼻蟲', '症狀：倒伏；確認方式：現地診察。', '官方歷史案例建議：該害蟲可從植物的傷口處入侵,應減少割草時對樹木的傷害,避免基部破損,才能有效阻止該蟲害的進入。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-0aa88e0873ad1ad5a9aa3133');
