INSERT INTO `pests` (`pest_id`, `crop_id`, `pest_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (185, 925, '白蟻', '症狀：先前經貴所診斷為褐根病，滋生白蟻樹葉泛黃情形。；確認方式：現地診察。', '官方歷史案例建議：請再施作一次褐根腐病的防治措施，白蟻部份直接使用水柱將樹幹上的蟲子及蟻窩沖洗下來並保持乾燥即可。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-41ff80fbc4ffeed10370ed98');
