INSERT INTO `pests` (`pest_id`, `crop_id`, `pest_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (187, 925, '紫膠介殼蟲', '症狀：葉片呈黑色、枝條被膠狀物包覆；受害描述：經會勘發現，南瀛總爺藝文中心大門口之榕樹係遭受紫膠介殼蟲危害，其分泌進而誘發煤煙病，使葉片呈現黑色狀。；確認方式：現地診察。', '此官方歷史案例含特定藥劑、濃度或施用方式，可能不符合目前核准用法，系統不直接回傳該舊處方。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-ab8ce9b87d8f9a5bb5f63345');
