INSERT INTO `pests` (`pest_id`, `crop_id`, `pest_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (189, 928, '木蠹蛾', '症狀：枝條被鑽蛀；確認方式：樣本檢驗。', '官方歷史案例建議：直接將有蟲糞排出（正下方地表會有蟲糞落下）及已炸銂漕`枝條修除燒燬即可。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-27d02d1cd4a677289ec8a200');
