INSERT INTO `pests` (`pest_id`, `crop_id`, `pest_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (195, 934, '台灣家白蟻', '症狀：花壇植栽有部分枯死，兩株有明顯蟻道。；確認方式：現地診察。', '官方歷史案例建議：移除病死株，更換花壇土壤，溺死土壤白蟻。請防蟲公司處理天花板與頂樓間的白蟻，其餘暫不用藥。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-a659d522648ceab0d78e0102');
