INSERT INTO `pests` (`pest_id`, `crop_id`, `pest_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (198, 936, '白蟻', '症狀：樹幹從根部開始長白蟻侵蝕樹幹；確認方式：現地診察。', '官方歷史案例建議：可分兩部分處理。土壤部份，較嚴重危害的樹基部先用水泥推砌成一土圈後，已灌水方式灌於樹基部，每株大約需50公升，每天一次，連續兩週。樹幹部份則以水柱直接沖洗白蟻窩，保持樹幹乾淨不要再築巢即可。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-efcb3c44989c513321fa9af9');
