INSERT INTO `pests` (`pest_id`, `crop_id`, `pest_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (202, 941, '天牛', '症狀：根基部有大量排遺；確認方式：現地診察。', '官方歷史案例建議：現場勘查發現為天牛危害建議參考星天牛之防除方法加以防除。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-fc7ea0203a20f3183bd453cb');
INSERT INTO `pests` (`pest_id`, `crop_id`, `pest_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (203, 946, '紅胸葉蟲', '症狀：葉片逐漸枯萎；受害描述：成、幼蟲皆食害未展開的心葉，已展開者不再危害，被食害葉片附近變褐色而乾枯，受害嚴重者，葉片完全乾枯；而致全株枯死。 卵產在未展開之新葉上，呈扁平長橢圓形、表面密被龜甲狀的點刻。 幼蟲及成蟲均食害未展開扇摺狀新葉的上、下表皮及葉肉食痕呈條狀。近生長點較緊密葉片或已展開之葉片不被危害。被危害部份變褐色並有褐色粉狀排泄物，其後逐漸乾枯。；確認方式：現地診察。', '此官方歷史案例含特定藥劑、濃度或施用方式，可能不符合目前核准用法，系統不直接回傳該舊處方。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-2f96a8570c3dca50e7e9550e');
INSERT INTO `pests` (`pest_id`, `crop_id`, `pest_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (204, 825, '棉介殼蟲', '症狀：莖、枝條有白色棉絮狀物；確認方式：樣本檢驗。', '此官方歷史案例含特定藥劑、濃度或施用方式，可能不符合目前核准用法，系統不直接回傳該舊處方。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-b9a3c0d05e46da05b26ad53c');
INSERT INTO `pests` (`pest_id`, `crop_id`, `pest_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (205, 825, '烏心石幹綿蚜', '症狀：樹幹本身佈滿白色粉狀斑，受害嚴重之樹株整株樹幹變白。；確認方式：樣本檢驗。', '此官方歷史案例含特定藥劑、濃度或施用方式，可能不符合目前核准用法，系統不直接回傳該舊處方。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-720e908298b0cac0feec85a9');
INSERT INTO `pests` (`pest_id`, `crop_id`, `pest_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (206, 952, '刺桐釉小蜂', '症狀：葉子有蟲癭發生、落葉及枯萎現象；確認方式：現地診察。', '官方歷史案例建議：約定現勘時間現場處理。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-62469f950abd6657dd911d35');
INSERT INTO `pests` (`pest_id`, `crop_id`, `pest_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (207, 960, '銀葉粉蝨', '症狀：白色小蟲體；受害描述：白色小蟲,多群棲於葉背,受震動時飛起但很快又停在附近。如蟲淡黃色體型小,扁橢圓形,初齡幼蟲會移動,但很快就固定在葉背不移動，刺吸汁液, 使植株生長衰弱,卵殼、蟲體、蛻皮及煤煙污染植株。；確認方式：現地診察。', '此官方歷史案例含特定藥劑、濃度或施用方式，可能不符合目前核准用法，系統不直接回傳該舊處方。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-018c03c719f542ae3c4c549f');
INSERT INTO `pests` (`pest_id`, `crop_id`, `pest_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (208, 961, '根瘤線蟲', '症狀：底部枝條、葉分枝逐漸往上乾?>；確認方式：現地診察。', '官方歷史案例建議：為根瘤線蟲導致之樹木生長衰落最後被其他真菌入侵根部而逐漸炸銦A建議立即移除受害植株，再以殺線蟲劑進行土壤灌注消毒。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-a607c811e3d20147e517ba62');
