INSERT INTO `pests` (`pest_id`, `crop_id`, `pest_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (217, 983, '紫膠介殼蟲', '症狀：全株落葉；確認方式：現地診察。', '官方歷史案例建議：大量落葉是由樹木基部水泥固封所引起的，建議儘速使用徒手方式加以清除水泥，以維植物水份及養分的正常吸收。紫膠介殼蟲所危害的枝條，直接修枝清除並銷毀即可。在清理樹基部水泥後，可施以有機肥一次，來增加植物的生長情形。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-70b065f35375a5945cb64e18');
