INSERT INTO `pests` (`pest_id`, `crop_id`, `pest_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (219, 989, '紅胸葉蟲', '症狀：新葉枯黃；確認方式：現地診察。', '此官方歷史案例含特定藥劑、濃度或施用方式，可能不符合目前核准用法，系統不直接回傳該舊處方。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-b8e32ea234716743b329d167');
INSERT INTO `pests` (`pest_id`, `crop_id`, `pest_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (220, 717, '蘇鐵白輪盾介殼蟲', '症狀：葉片長滿白色蟲體；受害描述：蘇鐵白輪盾介殼蟲可危害蘇鐵全株，包括葉片、莖球及根部等，常在葉片基部、葉軸和羽狀小葉的下表面吸食汁液，使葉片黃化枯萎、脫落，嚴重可導致全株枯死。蘇鐵白輪盾介殼蟲繁殖能力強，可藉由風、人為攜帶或苗木遷移，作長距離擴散。防治方法剪除受感染葉片，避免成為感染源。；確認方式：現地診察。', '此官方歷史案例含特定藥劑、濃度或施用方式，可能不符合目前核准用法，系統不直接回傳該舊處方。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-bd4d520c853ba24acf512764');
