INSERT INTO `pests` (`pest_id`, `crop_id`, `pest_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (224, 1008, '刺桐釉小蜂', '症狀：刺桐釉小蜂危害；確認方式：現地診察。', '此官方歷史案例含特定藥劑、濃度或施用方式，可能不符合目前核准用法，系統不直接回傳該舊處方。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-071d495809bfb23750b6090d');
INSERT INTO `pests` (`pest_id`, `crop_id`, `pest_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (225, 1010, '楓粉蝨', '症狀：枯葉、枯枝、掉綠葉。；確認方式：樣本檢驗。', '此官方歷史案例含特定藥劑、濃度或施用方式，可能不符合目前核准用法，系統不直接回傳該舊處方。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-a910baa28b382f4fe4445c0e');
INSERT INTO `pests` (`pest_id`, `crop_id`, `pest_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (226, 1012, '白蟻', '症狀：樹幹被白蟻蛀蝕；確認方式：現地診察。', '官方歷史案例建議：天氣常時間乾旱，樹木遭受白蟻為害時，建議使用灌水方式來防治。水柱沖洗樹幹受害部位，另外，用徒手工具將樹基部周圍挖出溝渠後，再大量灌水淹沒蟻窩，每日二次，持續1-2週。若還有白蟻出現才使用白蟻藥，灌注於樹基部內，此藥毒性甚強使用要非常小心，避免人員靠近。但樹幹若柱蝕出現中空現象，恐有傾倒之危險，建議砍除以維安全。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-f32530689efe25dd5af038b2');
INSERT INTO `pests` (`pest_id`, `crop_id`, `pest_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (227, 1012, '鳳凰木夜蛾', '症狀：不明小蟲吃光整株樹葉；確認方式：樣本檢驗。', '此官方歷史案例含特定藥劑、濃度或施用方式，可能不符合目前核准用法，系統不直接回傳該舊處方。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-ec0571fd8ae384d6ff4ce696');
INSERT INTO `pests` (`pest_id`, `crop_id`, `pest_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (228, 1014, '螨', '症狀：葉部有類似蟲嬰現像以及葉部有明鮮的呈現橘色現像；確認方式：樣本檢驗。', '此官方歷史案例含特定藥劑、濃度或施用方式，可能不符合目前核准用法，系統不直接回傳該舊處方。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-ee9b2d85ae39377a17c31078');
INSERT INTO `pests` (`pest_id`, `crop_id`, `pest_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (229, 1015, '刺桐釉小蜂', '症狀：刺桐釉小蜂 及 蛾類幼蟲 危害；確認方式：現地診察。', '官方歷史案例建議：由於園區屬於半封閉空間，全區僅有上述30株刺桐屬植物，所以建議將較小的植株予以移除，取代種植其它非刺桐屬植物，而景觀台周圍的9株大樹，應依據建議，給予藥物防治和支持性治療(供水及供養份)。其它建議如下: (1)請依據摺頁上之防治方法，進行操作，相關藥品可向用林務局提申請。 (2)進入夏季後較乾燥少雨，應該每週給予植株1次供水，每次每株至少20公升; 另外，也可以每季給予合適的肥料，提高樹木營養和活力。 (3)根據試驗，修枝並不具有防治效果，但是，掉落的枝條和葉片則應該集中收集焚毀或是密封，讓枝葉中的幼蟲死亡。 (4)已經死亡的植株可將較高而徑較細的枝條修剪和移除，但是可以保留主要樹幹，供鳥類營巢或刻成木雕供解說教育。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-edb065bcbbdc6aa76f2b44ce');
INSERT INTO `pests` (`pest_id`, `crop_id`, `pest_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (230, 1016, '刺桐釉小蜂', '症狀：蟲癭；確認方式：現地診察。', '官方歷史案例建議：益達胺搭配黃色黏紙 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-6aea4df48e224c7e6dcadbbb');
INSERT INTO `pests` (`pest_id`, `crop_id`, `pest_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (231, 837, '松材線蟲', '症狀：葉逐漸乾枯；確認方式：現地診察。', '此官方歷史案例含特定藥劑、濃度或施用方式，可能不符合目前核准用法，系統不直接回傳該舊處方。請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-3f4c4beda964eccbde9bc0e2');
INSERT INTO `pests` (`pest_id`, `crop_id`, `pest_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (232, 1019, 'mite’s gall', '症狀：造癭；確認方式：現地診察。', '官方歷史案例建議：不詳,未採集過本節肢動物,尚鑑定中 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-41d4f68013021c9ec4c8fed4');
INSERT INTO `pests` (`pest_id`, `crop_id`, `pest_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (233, 1019, '白蟻或天牛蛀蝕', '症狀：根莖蛀蝕腐爛；確認方式：樣本檢驗。', '官方歷史案例建議：根據隨信附上之圖片檔判斷，應為天牛或白蟻蛀蝕造成樹幹腐朽，樹幹若柱蝕出現中空現象，恐有傾倒之危險，建議砍除以維護安全。 郵寄送達之樣本，近期將會替您化驗，若判定有褐根病危害，需進行土壤燻蒸處理，以避免疫情擴散。 請由農業專業人員確認，並依農業部現行核准資訊與產品標示處理；請勿只依影像辨識結果自行施藥。', '農業部樹木病蟲害診斷案例', 'https://data.moa.gov.tw/api/v1/TreePestInfoType/', 'tree-3594577a64f043674317eb03');
INSERT INTO `pests` (`pest_id`, `crop_id`, `pest_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (234, 639, '二點葉蟎 (Spider Mites)', '成蟲和若蟲聚集在葉背吸取汁液，葉面呈現微細黃白色褪綠斑點，嚴重時葉片枯黃捲縮脫落，並於葉背與嫩芽吐絲結網。', '1. 保持田間濕潤，乾旱有利其快速繁殖。\n2. 釋放捕食蟎等天敵生物防治。\n3. 發生初期選用阿維菌素、噠蟎靈或螺蟎酯等登記殺蟎劑進行全面噴霧。', 'PlantVillage', NULL, NULL);
INSERT INTO `pests` (`pest_id`, `crop_id`, `pest_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (235, 901, '葉蟎危害', '- 葉片表面出現密集細小的褪綠黃白色微小斑駁斑點，葉色顯得粗糙且光澤度下降，為葉蟎在葉背刺吸汁液破壞葉綠素的典型初中期徵狀。\n- 葉蟎在乾燥悶熱環境下繁殖極為迅速，若不及時防治，葉片將逐漸黃化乾枯並提早脫落，嚴重時會在嫩梢處吐絲結網，大幅削弱植株生長勢與開花能力。', '1. 物理沖洗與修剪：葉蟎喜好乾燥環境，初期可利用水柱定期由下往上強力沖洗葉背以降低蟲口密度，同時適度修剪通風不良及受害嚴重的枝葉並集中清除。\n2. 友善資材防治：施用窄域油、苦楝油乳劑或脂肪酸鉀鹽（稀釋約500-800倍），每隔5-7天噴施一次，噴灑時務必全面均勻覆蓋葉背與葉面，藉由物理包覆窒息害蟎。\n3. 化學藥劑輪替：若危害嚴重，可參考農業部登記於花卉類之殺蟎劑（如賜派芬、依殺蟎或芬殺蟎等），選用兩種以上不同作用機制的藥劑輪流噴灑，以避免葉蟎快速產生抗藥性。', '農業部動植物防疫檢疫署害蟲防治指引', 'https://www.aphia.gov.tw', 'aphia-pest-235');
INSERT INTO `pests` (`pest_id`, `crop_id`, `pest_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (236, 932, '柑橘葉蟎', '- 葉片表面呈現密集失綠微斑與黃化焦枯，為柑橘葉蟎刺吸汁液所致，嚴重削弱光合作用機能。\n- 乾旱季節葉蟎繁殖迅速，若未即時壓制將引發大量落葉與果皮粗糙褐化，嚴重影響收成品質。', '1. 修剪清園：剪除樹冠內部密集枝條與嚴重褐化老葉並移出銷毀，改善通風與日照以減少蟎類孳生源。\n2. 物理防治：全株噴施99%窄域油乳劑500倍液，重點噴灑葉背以窒息成蟎與卵，避免高溫正午施用。\n3. 藥劑防治：輪替噴施20%必芬蟎水懸劑2000倍液全面防治，需確實落實安全採收期並避免抗藥性產生。', '農業部動植物防疫檢疫署害蟲防治指引', 'https://www.aphia.gov.tw', 'aphia-pest-236');
INSERT INTO `pests` (`pest_id`, `crop_id`, `pest_name`, `description`, `treatment`, `source_name`, `source_url`, `source_record_id`) VALUES (237, 901, '葉蟎', '- 葉片表面出現密集細小的褪綠黃白色微小斑駁斑點，葉色顯得粗糙且光澤度下降，為葉蟎在葉背刺吸汁液破壞葉綠素的典型初中期徵狀。\n- 葉蟎在乾燥悶熱環境下繁殖極為迅速，若不及時防治，葉片將逐漸黃化乾枯並提早脫落，嚴重時會在嫩梢處吐絲結網，大幅削弱植株生長勢與開花能力。', '1. 物理沖洗與修剪：葉蟎喜好乾燥環境，初期可利用水柱定期由下往上強力沖洗葉背以降低蟲口密度，同時適度修剪通風不良及受害嚴重的枝葉並集中清除。\n2. 友善資材防治：施用窄域油、苦楝油乳劑或脂肪酸鉀鹽（稀釋約500-800倍），每隔5-7天噴施一次，噴灑時務必全面均勻覆蓋葉背與葉面，藉由物理包覆窒息害蟎。\n3. 化學藥劑輪替：若危害嚴重，可參考農業部登記於花卉類之殺蟎劑（如賜派芬、依殺蟎或芬殺蟎等），選用兩種以上不同作用機制的藥劑輪流噴灑，以避免葉蟎快速產生抗藥性。', '農業部動植物防疫檢疫署 (APHIA) 與 Gemini 多模態視覺病理知識庫', 'https://www.aphia.gov.tw', 'aphia-gemini-朱槿-葉蟎');
