INSERT INTO `plant_diary` (`id`, `user_id`, `crop_id`, `status_name`, `image_url`, `disease_id`, `pest_id`, `confidence`, `suggestion`, `treatment`, `user_note`, `created_at`, `user_corrected_status`, `requires_review`, `grounding_source`, `reference_source`, `reference_url`, `reference_record_id`, `category`) VALUES (20, 2, 2, 'Healthy', 'static\\uploads\\IMG_1331.jpg', NULL, NULL, 0.95, '此植物生長狀況良好，葉片翠綠飽滿，沒有病蟲害跡象。', '請繼續保持目前的良好管理，定期檢查，確保適當的水分和養分供應。', '259', '2026-04-11 00:33:02', NULL, 1, 'legacy_unverified', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-diary-20', 'unknown');
INSERT INTO `plant_diary` (`id`, `user_id`, `crop_id`, `status_name`, `image_url`, `disease_id`, `pest_id`, `confidence`, `suggestion`, `treatment`, `user_note`, `created_at`, `user_corrected_status`, `requires_review`, `grounding_source`, `reference_source`, `reference_url`, `reference_record_id`, `category`) VALUES (21, 2, 563, 'Healthy', 'static\\uploads\\下載 (2).jpg', NULL, NULL, 0.98, '照片中的番石榴外觀良好，無明顯病蟲害跡象，品質新鮮。', '建議繼續保持良好的種植環境與管理，以確保果實健康生長。', '123', '2026-04-12 23:57:33', NULL, 1, 'legacy_unverified', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-diary-21', 'unknown');
