INSERT INTO `plant_diary` (`id`, `user_id`, `crop_id`, `status_name`, `image_url`, `disease_id`, `pest_id`, `confidence`, `suggestion`, `treatment`, `user_note`, `created_at`, `user_corrected_status`, `requires_review`, `grounding_source`, `reference_source`, `reference_url`, `reference_record_id`, `category`) VALUES (23, 2, 16, 'Healthy', 'C:/Users/User/OneDrive/Desktop/plant_backend/static/uploads/0f3e530812de4ef9ba25cb78d46edb60.jpg', NULL, NULL, 0.85, '持續提供適當的光照、水分和營養，保持土壤良好通氣，預防病蟲害，以促進健康生長。', '目前無需治療。', '', '2026-04-23 23:07:24', NULL, 1, 'legacy_unverified', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-diary-23', 'unknown');
INSERT INTO `plant_diary` (`id`, `user_id`, `crop_id`, `status_name`, `image_url`, `disease_id`, `pest_id`, `confidence`, `suggestion`, `treatment`, `user_note`, `created_at`, `user_corrected_status`, `requires_review`, `grounding_source`, `reference_source`, `reference_url`, `reference_record_id`, `category`) VALUES (24, 2, 566, 'Healthy', 'C:/Users/User/OneDrive/Desktop/plant_backend/static/uploads/34143c74a2ee4a55988110bbd3a76c51.jpg', NULL, NULL, 0.98, 'The banana plant and its fruits appear to be healthy. Continue with regular cultivation practices, including adequate watering, nutrient management, and monitoring for any early signs of pests or diseases.', 'N/A', '', '2026-04-23 23:14:35', NULL, 1, 'legacy_unverified', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-diary-24', 'unknown');
INSERT INTO `plant_diary` (`id`, `user_id`, `crop_id`, `status_name`, `image_url`, `disease_id`, `pest_id`, `confidence`, `suggestion`, `treatment`, `user_note`, `created_at`, `user_corrected_status`, `requires_review`, `grounding_source`, `reference_source`, `reference_url`, `reference_record_id`, `category`) VALUES (25, 2, 563, 'Healthy', 'C:/Users/User/OneDrive/Desktop/plant_backend/static/uploads/01b3a335bafa4821bba456f1aa99776c.jpg', NULL, NULL, 0.95, 'The guavas appear healthy and in good condition. Continue with standard harvesting practices and ensure proper storage to maintain quality.', 'N/A', '', '2026-04-23 23:24:29', NULL, 1, 'legacy_unverified', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-diary-25', 'unknown');
INSERT INTO `plant_diary` (`id`, `user_id`, `crop_id`, `status_name`, `image_url`, `disease_id`, `pest_id`, `confidence`, `suggestion`, `treatment`, `user_note`, `created_at`, `user_corrected_status`, `requires_review`, `grounding_source`, `reference_source`, `reference_url`, `reference_record_id`, `category`) VALUES (26, 2, 563, 'Healthy', 'C:/Users/User/OneDrive/Desktop/plant_backend/static/uploads/2333db9245ef4a989a82d3f8fb3bdf34.jpg', NULL, NULL, 0.98, 'The guavas appear fresh and healthy.', 'No specific treatment is needed as the crop appears healthy.', '', '2026-04-23 23:24:51', NULL, 1, 'legacy_unverified', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-diary-26', 'unknown');
INSERT INTO `plant_diary` (`id`, `user_id`, `crop_id`, `status_name`, `image_url`, `disease_id`, `pest_id`, `confidence`, `suggestion`, `treatment`, `user_note`, `created_at`, `user_corrected_status`, `requires_review`, `grounding_source`, `reference_source`, `reference_url`, `reference_record_id`, `category`) VALUES (31, 2, 563, 'Healthy', 'D:/plant_backend/static/uploads/1b886943fa3344639b269a84d67d618d.jpg', NULL, NULL, 0.95, '這些番石榴看起來新鮮健康，建議清洗後即可食用或加工。為保持最佳風味與品質，建議儲存於陰涼通風處或冷藏。', '無', '123', '2026-05-04 02:00:53', '土壤過份乾燥', 1, 'legacy_unverified', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-diary-31', 'unknown');
INSERT INTO `plant_diary` (`id`, `user_id`, `crop_id`, `status_name`, `image_url`, `disease_id`, `pest_id`, `confidence`, `suggestion`, `treatment`, `user_note`, `created_at`, `user_corrected_status`, `requires_review`, `grounding_source`, `reference_source`, `reference_url`, `reference_record_id`, `category`) VALUES (32, 2, 566, 'Healthy', 'D:/plant_backend/static/uploads/b1daabbaa64c44b9824f2f536ff80df9.jpg', NULL, NULL, 0.95, '持續提供充足的陽光和水分，並定期施用均衡肥料，特別是富含鉀的肥料，以促進果實發育和植株健康。保持良好的土壤排水，並定期修剪枯黃或受損的葉片以維持通風，預防病蟲害。', '目前無需特殊處理，僅需維持良好的日常田間管理，確保植株持續健康生長及果實品質。', '', '2026-05-04 02:01:31', NULL, 1, 'legacy_unverified', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-diary-32', 'unknown');
INSERT INTO `plant_diary` (`id`, `user_id`, `crop_id`, `status_name`, `image_url`, `disease_id`, `pest_id`, `confidence`, `suggestion`, `treatment`, `user_note`, `created_at`, `user_corrected_status`, `requires_review`, `grounding_source`, `reference_source`, `reference_url`, `reference_record_id`, `category`) VALUES (35, 2, 4, 'Healthy', 'D:/plant_backend/static/uploads/df53a4429b9048bb8e031cf099c2168e.jpg', NULL, NULL, 0.85, '為了確保西瓜的良好生長與果實品質，建議在果實生長期間，使用墊材（如稻草、塑膠布或專用墊子）將果實與潮濕的土壤隔開，以減少「地斑」和病菌侵入的風險。同時，應避免果實受到機械性損傷，並確保植株獲得充足且均衡的養分與水分，以及良好的通風和適度的光照。定期檢查果實，及早發現並處理任何異常。', '圖片中西瓜表皮的斑點多為表皮性損傷或生理性變化，不像是活躍且具傳染性的病害，因此目前無需使用特定的農藥進行化學處理。重點應放在改善栽培管理上，預防新的損傷和斑點產生。若未來觀察到斑點擴大、軟爛或出現其他明顯病徵，則需進一步判斷病害種類，並依據病害特性選擇合適的生物防治方法或登記農藥進行處理。', '', '2026-05-11 23:31:03', NULL, 1, 'legacy_unverified', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-diary-35', 'unknown');
INSERT INTO `plant_diary` (`id`, `user_id`, `crop_id`, `status_name`, `image_url`, `disease_id`, `pest_id`, `confidence`, `suggestion`, `treatment`, `user_note`, `created_at`, `user_corrected_status`, `requires_review`, `grounding_source`, `reference_source`, `reference_url`, `reference_record_id`, `category`) VALUES (67, 2, 535, '痂病', 'D:/plant_backend/static/uploads/63a00eb815d24dc4a2fa0d3c04d6d05f.jpg', 26, NULL, 0.95, '「痂病」是蘋果常見的真菌性病害。建議採取綜合管理策略，包括：\n1.  清潔園區：定期清除並銷毀受感染的落葉、病果和病枝，減少病原體越冬來源。\n2.  改善通風：適度修剪果樹，使樹冠內部通風良好，增加光照，降低葉片和果實表面的濕度，不利於病菌生長。\n3.  選擇抗病品種：在新種植或更新果園時，優先選擇對痂病具有抗性的蘋果品種。\n4.  合理施肥：避免過量施用氮肥，以免枝葉生長過於茂盛，加劇通風不良問題。\n5.  灌溉管理：盡量使用滴灌或地面灌溉，避免葉片長時間濕潤。', '針對蘋果痂病，可以採用化學防治方法，但需與上述栽培管理措施結合使用，以達到最佳效果：\n1.  藥劑選擇：在病害高發期（如春季發芽至幼果期，雨水較多時），可使用針對真菌性病害的殺菌劑。常見有效成分包括：\n    *   保護性殺菌劑：如波爾多液、代森錳鋅、福美雙等，在病菌侵染前施用，形成保護膜。\n    *   治療性殺菌劑：如腈硫磺、氟矽唑、苯醚甲環唑、嘧菌酯等，在病害初期使用，具有內吸性或治療作用。\n2.  施藥時機：應根據當地氣候條件和病害發生規律，在關鍵時期（如銀梢期、粉紅芽期、開花期、花後及幼果期）進行預防性或治療性噴灑。雨前施藥尤為重要。\n3.  輪換用藥：為避免病菌產生抗藥性，建議不同作用機制的殺菌劑輪換使用。\n4.  遵守規範：嚴格按照農藥產品說明書的要求，控制施藥濃度、間隔期和安全採收期，確保食品安全。\n5.  專業指導：若情況嚴重，建議諮詢當地農業專家或植保站，獲取更具體的診斷和防治建議。', '1234', '2026-05-24 13:22:33', NULL, 1, 'legacy_unverified', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-diary-67', 'unknown');
INSERT INTO `plant_diary` (`id`, `user_id`, `crop_id`, `status_name`, `image_url`, `disease_id`, `pest_id`, `confidence`, `suggestion`, `treatment`, `user_note`, `created_at`, `user_corrected_status`, `requires_review`, `grounding_source`, `reference_source`, `reference_url`, `reference_record_id`, `category`) VALUES (76, 2, 527, '白粉病', 'D:/plant_backend/static/uploads/8b8e36c932734cccbe11c614c9312687.jpg', 21, NULL, 0.95, '- 果實表面出現不規則的白色粉狀斑點。\n- 感染部位的果實發育可能受阻。', '1. 修剪受感染的枝葉和果實，以減少病原體來源並改善植株通風。\n2. 施用核准的殺菌劑，例如硫磺粉或含生物防治成分的藥劑，並遵循產品說明進行噴灑。\n3. 改善種植環境通風，避免在夜間或傍晚進行頂部澆水，以減少葉片和果實表面的濕潤時間。', '', '2026-05-30 15:46:33', NULL, 1, 'legacy_unverified', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-diary-76', 'unknown');
INSERT INTO `plant_diary` (`id`, `user_id`, `crop_id`, `status_name`, `image_url`, `disease_id`, `pest_id`, `confidence`, `suggestion`, `treatment`, `user_note`, `created_at`, `user_corrected_status`, `requires_review`, `grounding_source`, `reference_source`, `reference_url`, `reference_record_id`, `category`) VALUES (81, 2, 3, '健康', 'D:/plant_backend/static/uploads/206488d0c4224accaaaa57ef0889809c.jpg', NULL, NULL, 0.98, '- 果實表皮有清晰且均勻的網紋\n- 果實顏色呈現健康且自然的色澤\n- 葉片呈現深綠色，無明顯病斑或蟲害跡象', '繼續保持良好照顧。', '', '2026-06-04 00:21:42', NULL, 1, 'legacy_unverified', '農業部農業試驗所作物生長健康常規指引', 'https://www.tari.gov.tw', 'tari-healthy-standard', 'unknown');
INSERT INTO `plant_diary` (`id`, `user_id`, `crop_id`, `status_name`, `image_url`, `disease_id`, `pest_id`, `confidence`, `suggestion`, `treatment`, `user_note`, `created_at`, `user_corrected_status`, `requires_review`, `grounding_source`, `reference_source`, `reference_url`, `reference_record_id`, `category`) VALUES (83, 14, 670, '健康', 'D:/plant_backend/static/uploads/877791c71aa44512b38ac01882aedd5b.jpg', NULL, NULL, 0.95, '- 葉片呈深綠色且有光澤。\n- 葉片飽滿，無枯黃、斑點或病蟲害跡象。\n- 植株生長茂盛，型態良好。', '繼續保持良好照顧。', 'good', '2026-06-10 15:36:09', NULL, 1, 'legacy_unverified', '農業部農業試驗所作物生長健康常規指引', 'https://www.tari.gov.tw', 'tari-healthy-standard', 'unknown');
INSERT INTO `plant_diary` (`id`, `user_id`, `crop_id`, `status_name`, `image_url`, `disease_id`, `pest_id`, `confidence`, `suggestion`, `treatment`, `user_note`, `created_at`, `user_corrected_status`, `requires_review`, `grounding_source`, `reference_source`, `reference_url`, `reference_record_id`, `category`) VALUES (84, 14, 471, '蟲害', 'D:/plant_backend/static/uploads/58e51d1aa32340fe9ec36f18ddca6b08.jpg', NULL, 1, 0.98, '- 葉片上可見褐色的蛞蝓\n- 葉片有許多不規則的孔洞\n- 葉緣被啃食導致不整齊', '1. 人工捕捉蛞蝓，尤其是在清晨、傍晚或雨後進行。\n2. 設置誘餌陷阱，例如啤酒陷阱或商業蛞蝓誘餌，以吸引並捕殺蛞蝓。\n3. 保持田園清潔，清除雜草和枯葉，減少蛞蝓的藏身之處。', '', '2026-06-10 15:39:21', NULL, 1, 'legacy_unverified', '農業部動植物防疫檢疫署害蟲防治指引', 'https://www.aphia.gov.tw', 'aphia-pest-diary-84', 'unknown');
INSERT INTO `plant_diary` (`id`, `user_id`, `crop_id`, `status_name`, `image_url`, `disease_id`, `pest_id`, `confidence`, `suggestion`, `treatment`, `user_note`, `created_at`, `user_corrected_status`, `requires_review`, `grounding_source`, `reference_source`, `reference_url`, `reference_record_id`, `category`) VALUES (85, 14, 566, '腐爛', 'D:/plant_backend/static/uploads/950c851755e14b7ba48ad7845a5e3060.jpg', 25, NULL, 0.95, '- 香蕉皮顏色深黃，並出現大面積的黑褐色斑點。\n- 香蕉果肉質地可能變軟。', '1. 若果實仍可食用，建議盡快食用或用於烹飪與烘焙。\n2. 為延緩香蕉腐爛，可將其從香蕉串中分離，或存放在陰涼乾燥處，避免與其他成熟水果一同存放。\n3. 若香蕉已嚴重腐爛，應丟棄以避免吸引害蟲並傳播黴菌。', '', '2026-06-10 15:39:53', NULL, 1, 'legacy_unverified', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-diary-85', 'unknown');
INSERT INTO `plant_diary` (`id`, `user_id`, `crop_id`, `status_name`, `image_url`, `disease_id`, `pest_id`, `confidence`, `suggestion`, `treatment`, `user_note`, `created_at`, `user_corrected_status`, `requires_review`, `grounding_source`, `reference_source`, `reference_url`, `reference_record_id`, `category`) VALUES (86, 14, 20, '葉斑病', 'D:/plant_backend/static/uploads/afdd608a42aa4750a6f83409de28ab66.jpg', 24, NULL, 0.85, '- 葉片呈現黃化，尤其在褐斑周圍\n- 葉片上出現不規則、深褐色的壞死斑塊\n- 壞死斑塊邊緣呈現乾燥狀', '1. 小心地移除受感染的葉片，以防止病害進一步擴散。\n2. 檢查盆土濕度，確保排水良好，避免土壤積水導致根部腐爛或病菌滋生。\n3. 暫時減少施肥，或用清水沖洗土壤以稀釋可能的肥料鹽分累積。\n4. 確保植物放置在通風良好且有充足散射光的地方，避免強烈直射陽光。', '123', '2026-06-10 15:50:23', NULL, 1, 'legacy_unverified', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-diary-86', 'unknown');
INSERT INTO `plant_diary` (`id`, `user_id`, `crop_id`, `status_name`, `image_url`, `disease_id`, `pest_id`, `confidence`, `suggestion`, `treatment`, `user_note`, `created_at`, `user_corrected_status`, `requires_review`, `grounding_source`, `reference_source`, `reference_url`, `reference_record_id`, `category`) VALUES (87, 2, 20, '葉斑病', 'D:/plant_backend/static/uploads/ba853bd5d351463ca577962e71ebcba4.jpg', 24, NULL, 0.85, '- 葉片上出現不規則的棕色壞死斑塊。\n- 壞死斑塊周圍的葉片呈現黃化現象。\n- 嚴重時葉片邊緣可能出現焦枯。', '1. 立即剪除並清除受感染的葉片，以防止病害進一步擴散。\n2. 改善植物周圍的空氣流通，並避免在葉片上澆水，減少過度潮濕的環境。\n3. 檢查土壤排水是否良好，確保不會積水，並給予均衡的肥料，避免過量或不足。', 'good plant2', '2026-06-10 22:54:28', NULL, 1, 'legacy_unverified', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-diary-87', 'unknown');
INSERT INTO `plant_diary` (`id`, `user_id`, `crop_id`, `status_name`, `image_url`, `disease_id`, `pest_id`, `confidence`, `suggestion`, `treatment`, `user_note`, `created_at`, `user_corrected_status`, `requires_review`, `grounding_source`, `reference_source`, `reference_url`, `reference_record_id`, `category`) VALUES (88, 2, 14, '健康', 'D:/plant_backend/static/uploads/f59854a79ffa4491a703f26260cc0dd2.jpg', NULL, NULL, 0.9, '- 目前影像未見資料庫已知病蟲害的明顯特徵', '1. 維持正常照護\n2. 定期從相同角度拍攝並比較變化', '', '2026-09-18 22:55:59', NULL, 1, 'legacy_unverified', '農業部農業試驗所作物生長健康常規指引', 'https://www.tari.gov.tw', 'tari-healthy-standard', 'unknown');
INSERT INTO `plant_diary` (`id`, `user_id`, `crop_id`, `status_name`, `image_url`, `disease_id`, `pest_id`, `confidence`, `suggestion`, `treatment`, `user_note`, `created_at`, `user_corrected_status`, `requires_review`, `grounding_source`, `reference_source`, `reference_url`, `reference_record_id`, `category`) VALUES (89, 2, 22, '健康', 'D:/plant_backend/static/uploads/6e06c108674f426495c82bdcd4573657.jpg', NULL, NULL, 0.9, '- 目前影像未見資料庫已知病蟲害的明顯特徵', '1. 維持正常照護\n2. 定期從相同角度拍攝並比較變化', '', '2026-09-18 22:59:07', NULL, 1, 'legacy_unverified', '農業部農業試驗所作物生長健康常規指引', 'https://www.tari.gov.tw', 'tari-healthy-standard', 'unknown');
INSERT INTO `plant_diary` (`id`, `user_id`, `crop_id`, `status_name`, `image_url`, `disease_id`, `pest_id`, `confidence`, `suggestion`, `treatment`, `user_note`, `created_at`, `user_corrected_status`, `requires_review`, `grounding_source`, `reference_source`, `reference_url`, `reference_record_id`, `category`) VALUES (90, 2, 535, '健康', 'D:/plant_backend/static/uploads/b7900149a4f54423b842a60157064816.jpg', NULL, NULL, 0.98, '- 目前影像未見資料庫已知病蟲害的明顯特徵', '1. 維持正常照護\n2. 定期從相同角度拍攝並比較變化', '', '2026-09-18 23:01:46', NULL, 1, 'legacy_unverified', '農業部農業試驗所作物生長健康常規指引', 'https://www.tari.gov.tw', 'tari-healthy-standard', 'unknown');
INSERT INTO `plant_diary` (`id`, `user_id`, `crop_id`, `status_name`, `image_url`, `disease_id`, `pest_id`, `confidence`, `suggestion`, `treatment`, `user_note`, `created_at`, `user_corrected_status`, `requires_review`, `grounding_source`, `reference_source`, `reference_url`, `reference_record_id`, `category`) VALUES (91, 2, 4, '黴菌腐爛', 'D:/plant_backend/static/uploads/bb697e3467a1423fbf8873547fe661ad.jpg', 220, NULL, 0.98, '- 西瓜果肉表面覆蓋大面積灰白色至淺綠色的絨毛狀黴菌菌落。\n- 果肉組織已明顯軟爛、分解，呈現濕潤黏稠狀。', '1. 立即丟棄受感染的西瓜，切勿食用或嘗試切除受損部分食用，以免攝入有害黴菌毒素。\n2. 徹底清潔任何與腐爛西瓜接觸過的刀具、砧板、檯面及儲存容器，使用肥皂水或稀釋漂白水消毒，防止黴菌孢子擴散。\n3. 檢查並改善西瓜的儲存環境，確保儲存在陰涼、乾燥且通風良好的地方，避免陽光直射和潮濕。\n4. 未來購買或儲存西瓜時，選擇外皮完整無損、無裂口或擦傷的果實，並儘早食用。', '', '2026-09-19 00:49:13', NULL, 1, 'legacy_unverified', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-diary-91', 'unknown');
INSERT INTO `plant_diary` (`id`, `user_id`, `crop_id`, `status_name`, `image_url`, `disease_id`, `pest_id`, `confidence`, `suggestion`, `treatment`, `user_note`, `created_at`, `user_corrected_status`, `requires_review`, `grounding_source`, `reference_source`, `reference_url`, `reference_record_id`, `category`) VALUES (92, 2, 632, '灰黴病', 'D:/plant_backend/static/uploads/5deb33a785e741149d96b390ae283e1b.jpg', 221, NULL, 0.98, '- 果實表面出現白色至灰色的絨毛狀黴菌層\n- 受感染果實組織軟化、水漬狀腐爛\n- 病害常從果實表面受損處或萼片處開始發展', '1. 移除並銷毀所有受感染的果實及植物殘體，避免病菌擴散。\n2. 改善田間或儲藏環境的通風，降低相對濕度。\n3. 適當修剪植株，保持植株間距，減少葉片過度茂密。\n4. 採收時輕拿輕放，避免造成果實損傷，減少病菌侵入機會。\n5. 在病害高發期或環境條件有利於病害發生時，可依據當地農業推廣建議，選擇合適的殺菌劑進行預防或治療性噴灑。', '123', '2026-09-19 00:55:23', NULL, 1, 'legacy_unverified', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-diary-92', 'unknown');
INSERT INTO `plant_diary` (`id`, `user_id`, `crop_id`, `status_name`, `image_url`, `disease_id`, `pest_id`, `confidence`, `suggestion`, `treatment`, `user_note`, `created_at`, `user_corrected_status`, `requires_review`, `grounding_source`, `reference_source`, `reference_url`, `reference_record_id`, `category`) VALUES (93, 2, 1023, '缺鐵症', 'D:/plant_backend/static/uploads/fdf3930cd2d545c0b57307e36dff23c5.jpg', 223, NULL, 0.95, '- 新生葉片呈現明顯的葉脈間黃化，而葉脈仍保持綠色。\n- 葉片整體顏色較為淡黃，生長勢減弱。', '1. 檢查土壤酸鹼度 (pH值)：扶桑適合微酸性至中性土壤 (pH 6.0-7.0)。若土壤過於鹼性，會導致鐵質難以吸收。可施用硫磺粉或酸性有機質肥料來調整土壤pH值。\n2. 補充螯合鐵肥：立即施用螯合鐵肥 (如EDTA鐵、DTPA鐵等)，可進行葉面噴施或土壤灌注，效果較快且穩定。\n3. 改善土壤通氣與排水：避免土壤長時間積水或過於密實，良好的土壤通氣有助於根部健康生長和養分吸收。', '', '2026-09-22 00:39:52', NULL, 1, 'legacy_unverified', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-diary-93', 'unknown');
INSERT INTO `plant_diary` (`id`, `user_id`, `crop_id`, `status_name`, `image_url`, `disease_id`, `pest_id`, `confidence`, `suggestion`, `treatment`, `user_note`, `created_at`, `user_corrected_status`, `requires_review`, `grounding_source`, `reference_source`, `reference_url`, `reference_record_id`, `category`) VALUES (94, 2, 14, '健康', 'D:/plant_backend/static/uploads/88ff4db09eb747eeb12ef5d2968e2925.jpg', NULL, NULL, 0.95, '- 葉片呈現健康的深綠色，光澤良好。\n- 葉脈清晰，葉片組織飽滿，無明顯病斑、黃化、枯萎或穿孔。\n- 葉緣自然波浪狀，為作物正常生長形態。', '1. 維持適當的光照、溫度和濕度，確保植株有良好的生長環境。\n2. 提供均衡的氮磷鉀肥料，並定期補充微量元素，促進健康生長。\n3. 定期檢查葉片，及早發現並預防潛在的病蟲害問題。', '', '2026-09-22 00:40:40', NULL, 1, 'legacy_unverified', '農業部農業試驗所作物生長健康常規指引', 'https://www.tari.gov.tw', 'tari-healthy-standard', 'unknown');
INSERT INTO `plant_diary` (`id`, `user_id`, `crop_id`, `status_name`, `image_url`, `disease_id`, `pest_id`, `confidence`, `suggestion`, `treatment`, `user_note`, `created_at`, `user_corrected_status`, `requires_review`, `grounding_source`, `reference_source`, `reference_url`, `reference_record_id`, `category`) VALUES (95, 2, 1024, '葉斑病', 'D:/plant_backend/static/uploads/cc372951844d4de18d476737b13236e1.jpg', 24, NULL, 0.9, '- 葉片上出現不規則形狀的紅褐色至紫褐色斑點\n- 斑點散佈於葉片表面\n- 部分斑點擴大並融合，尤其是在葉緣附近', '1. 修剪並清除受感染的葉片及植株殘體，以減少病原殘存及傳播。\n2. 改善植株周圍的通風，確保葉片能迅速乾燥，降低病害發生條件。\n3. 避免傍晚澆水或使用噴灌，以減少葉面長時間濕潤。\n4. 嚴重情況下，可施用推薦的廣效性殺菌劑（如含代森錳鋅、百菌清或銅製劑的產品），並按照產品說明使用。', '', '2026-09-22 00:43:29', NULL, 1, 'legacy_unverified', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-diary-95', 'unknown');
INSERT INTO `plant_diary` (`id`, `user_id`, `crop_id`, `status_name`, `image_url`, `disease_id`, `pest_id`, `confidence`, `suggestion`, `treatment`, `user_note`, `created_at`, `user_corrected_status`, `requires_review`, `grounding_source`, `reference_source`, `reference_url`, `reference_record_id`, `category`) VALUES (97, 2, 632, '灰黴病', 'D:/plant_backend/static/uploads/b3727a32573d498488ed2e5e8b53fbe4.jpg', 221, NULL, 0.98, '- 草莓果實表面呈現淺棕色或暗棕色的軟腐斑塊。\n- 患病部位覆蓋有灰白色至灰褐色的絨毛狀黴菌層。\n- 受感染的果實會變得軟爛，失去原有光澤。', '1. 立即將受感染的草莓移除並丟棄，以防病害擴散至其他健康果實。\n2. 確保儲存環境保持乾燥、涼爽且通風良好，以抑制黴菌生長。\n3. 避免草莓在處理和儲存過程中受到機械性損傷，減少病原菌侵入的機會。', '', '2026-10-05 08:31:03', NULL, 0, 'gemini_multimodal_fallback', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-diary-97', 'disease');
INSERT INTO `plant_diary` (`id`, `user_id`, `crop_id`, `status_name`, `image_url`, `disease_id`, `pest_id`, `confidence`, `suggestion`, `treatment`, `user_note`, `created_at`, `user_corrected_status`, `requires_review`, `grounding_source`, `reference_source`, `reference_url`, `reference_record_id`, `category`) VALUES (98, 2, 535, '健康', 'D:/plant_backend/static/uploads/817d713b678b4582b4a4f9d4bb8d388c.jpg', NULL, NULL, 0.98, '- 植株生長強健，葉色均勻鮮綠，無枯黃萎凋或異常捲曲變形\n- 葉面及葉背均無明顯病斑、白粉、黴菌或害蟲侵蝕痕跡', '1. 維持當前適度日照與澆水頻率，避免盆土長期積水爛根。\n2. 保持良好通風環境，適時修剪老葉促進通風與生長。\n3. 定期檢查葉背與莖部新芽，持續做好日常田間衛生與預防。', '', '2026-10-05 08:38:00', NULL, 0, 'gemini_multimodal_fallback', '農業部農業試驗所作物生長健康常規指引', 'https://www.tari.gov.tw', 'tari-healthy-standard', 'healthy');
INSERT INTO `plant_diary` (`id`, `user_id`, `crop_id`, `status_name`, `image_url`, `disease_id`, `pest_id`, `confidence`, `suggestion`, `treatment`, `user_note`, `created_at`, `user_corrected_status`, `requires_review`, `grounding_source`, `reference_source`, `reference_url`, `reference_record_id`, `category`) VALUES (99, 2, 4, '黴菌腐爛', 'D:/plant_backend/static/uploads/37aec2045206428e8e7b0cd5d5ead932.jpg', 220, NULL, 0.98, '- 影像中的作物明顯為西瓜，其特徵是內部紅色果肉和外部綠色帶條紋的果皮。\n- 切開的果肉表面覆蓋著大片灰白色與綠色的絨毛狀黴菌菌絲。\n- 果肉質地已明顯變質，呈現濕軟、腐敗的狀態。', '1. 受黴菌感染的西瓜已不宜食用，應立即將其丟棄以避免健康風險。\n2. 處理過黴菌西瓜的刀具、砧板及容器應徹底清潔消毒，防止黴菌孢子傳播。\n3. 為預防未來發生，購買西瓜時應選擇外觀完整、無破損的果實。\n4. 切開的西瓜若未能一次食用完畢，務必用保鮮膜妥善密封後冷藏，並於短時間內儘速食用。', '', '2026-10-05 17:05:43', NULL, 0, 'gemini_multimodal_fallback', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-diary-99', 'disease');
INSERT INTO `plant_diary` (`id`, `user_id`, `crop_id`, `status_name`, `image_url`, `disease_id`, `pest_id`, `confidence`, `suggestion`, `treatment`, `user_note`, `created_at`, `user_corrected_status`, `requires_review`, `grounding_source`, `reference_source`, `reference_url`, `reference_record_id`, `category`) VALUES (100, 2, 4, '黴菌腐爛', 'D:/plant_backend/static/uploads/96b59faaffda4834a308e224d0213fc8.jpg', 220, NULL, 1.0, '- 果肉表面覆蓋大範圍灰白色及綠色黴菌。\n- 果肉組織已明顯軟化、液化，並呈現黏稠狀。\n- 瓜皮外觀顯示為典型西瓜的綠色帶深綠條紋，與使用者指定作物【三角桔梗】明顯不符。', '1. 該西瓜已嚴重腐爛，不適合食用，應立即丟棄以避免食品安全風險。\n2. 檢查其他儲存的農產品，確保儲存環境保持乾燥、通風良好，以預防黴菌滋生。\n3. 日後應仔細檢查農產品是否有損傷或腐爛跡象，及早處理，並避免存放過久。', '123456', '2026-10-07 02:16:30', NULL, 0, 'gemini_multimodal_fallback', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-diary-100', 'disease');
INSERT INTO `plant_diary` (`id`, `user_id`, `crop_id`, `status_name`, `image_url`, `disease_id`, `pest_id`, `confidence`, `suggestion`, `treatment`, `user_note`, `created_at`, `user_corrected_status`, `requires_review`, `grounding_source`, `reference_source`, `reference_url`, `reference_record_id`, `category`) VALUES (101, 2, 932, '營養缺乏', 'D:/plant_backend/static/uploads/61ff3b51f1cb4633a87c8d626c79487b.jpg', 255, NULL, 0.85, '🌟 【專家覆核校正】：原診斷為【營養缺乏】，經專家複審校正為【123】。\n- 檸檬果實呈橢圓形，表面有粗糙顆粒狀表皮，成熟時為黃色。\n- 葉片呈現普遍性黃化及部分褐斑，特別是老葉部分，顯示營養不良跡象。\n- 葉片未見明顯的特定病害斑點或蟲害痕跡。', '1. 進行土壤及葉片分析，以確定確切的營養缺乏類型（例如鎂、氮、鉀或其他微量元素）。\n2. 根據檢測結果，施用適量且平衡的肥料，針對性補充缺乏的養分。\n3. 確保提供適當的水分管理，避免土壤過乾或過濕，並改善土壤排水與通氣性。', '123456789', '2026-10-07 02:17:32', '123', 0, 'gemini_multimodal_fallback', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-diary-101', 'disease');
INSERT INTO `plant_diary` (`id`, `user_id`, `crop_id`, `status_name`, `image_url`, `disease_id`, `pest_id`, `confidence`, `suggestion`, `treatment`, `user_note`, `created_at`, `user_corrected_status`, `requires_review`, `grounding_source`, `reference_source`, `reference_url`, `reference_record_id`, `category`) VALUES (102, 2, 632, '灰黴病', 'D:/plant_backend/static/uploads/3b8b1018925d4ede9f920e480abbded4.jpg', 221, NULL, 0.98, '- 果實表面出現灰白色至灰褐色絨毛狀黴菌。\n- 受感染部位果肉軟化並腐爛。', '1. 立即移除並銷毀所有受感染的草莓，以防止病害擴散。\n2. 儲存時保持低溫（0-2°C）和適當的濕度（約90-95%），避免高濕環境。\n3. 確保草莓採收後盡快食用或冷藏，減少貯藏時間，降低病原發展機會。', '', '2026-10-13 19:30:43', NULL, 0, 'gemini_multimodal_fallback', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-diary-102', 'disease');
INSERT INTO `plant_diary` (`id`, `user_id`, `crop_id`, `status_name`, `image_url`, `disease_id`, `pest_id`, `confidence`, `suggestion`, `treatment`, `user_note`, `created_at`, `user_corrected_status`, `requires_review`, `grounding_source`, `reference_source`, `reference_url`, `reference_record_id`, `category`) VALUES (103, 2, 535, '健康', 'D:/plant_backend/static/uploads/a98963d643ae40c2b0fa72350a87d0c0.jpg', NULL, NULL, 0.95, '- 植株生長強健，葉色均勻鮮綠，無枯黃萎凋或異常捲曲變形\n- 葉面及葉背均無明顯病斑、白粉、黴菌或害蟲侵蝕痕跡', '1. 維持當前適度日照與澆水頻率，避免盆土長期積水爛根。\n2. 保持良好通風環境，適時修剪老葉促進通風與生長。\n3. 定期檢查葉背與莖部新芽，持續做好日常田間衛生與預防。', '', '2026-10-13 20:34:01', NULL, 0, 'gemini_multimodal_fallback', '農業部農業試驗所作物生長健康常規指引', 'https://www.tari.gov.tw', 'tari-healthy-standard', 'healthy');
INSERT INTO `plant_diary` (`id`, `user_id`, `crop_id`, `status_name`, `image_url`, `disease_id`, `pest_id`, `confidence`, `suggestion`, `treatment`, `user_note`, `created_at`, `user_corrected_status`, `requires_review`, `grounding_source`, `reference_source`, `reference_url`, `reference_record_id`, `category`) VALUES (104, 2, 759, '健康', 'D:/plant_backend/static/uploads/c7acdf30186e4acab8472a3a45902d4f.jpg', NULL, NULL, 0.95, '- 植株生長強健，葉色均勻鮮綠，無枯黃萎凋或異常捲曲變形\n- 葉面及葉背均無明顯病斑、白粉、黴菌或害蟲侵蝕痕跡', '1. 維持當前適度日照與澆水頻率，避免盆土長期積水爛根。\n2. 保持良好通風環境，適時修剪老葉促進通風與生長。\n3. 定期檢查葉背與莖部新芽，持續做好日常田間衛生與預防。', '', '2026-10-13 20:35:41', NULL, 0, 'gemini_multimodal_fallback', '農業部農業試驗所作物生長健康常規指引', 'https://www.tari.gov.tw', 'tari-healthy-standard', 'healthy');
INSERT INTO `plant_diary` (`id`, `user_id`, `crop_id`, `status_name`, `image_url`, `disease_id`, `pest_id`, `confidence`, `suggestion`, `treatment`, `user_note`, `created_at`, `user_corrected_status`, `requires_review`, `grounding_source`, `reference_source`, `reference_url`, `reference_record_id`, `category`) VALUES (105, 2, 901, '缺鐵症', 'D:/plant_backend/static/uploads/842191702dc74aa8b179625e57872ebf.jpg', 257, NULL, 0.88, '- 頂端嫩葉脈間黃化：照片中新葉呈現典型的「脈間失綠」特徵，葉肉部分褪綠變黃，而主要葉脈仍保持深綠，符合鐵元素在植體中移動性差的生理性缺鐵病徵。\n- 生長受阻與葉片壞疽風險：若缺鐵情況持續惡化，新葉將進一步泛白甚至由葉緣乾枯褐化，導致植株光合作用效率大幅下降、生長停滯並嚴重影響花芽分化。', '1. 應急葉面噴施螯合鐵：可使用水溶性螯合鐵肥（如 EDTA-Fe 或 EDDHA-Fe）依產品標示稀釋（通常為 1000-1500 倍），於清晨或傍晚葉面均勻噴施，每隔 7-10 天一次，連續 2-3 次以迅速改善新葉症狀。\n2. 檢測並調節介質酸鹼度（pH）：朱槿喜微酸性土壤（pH 6.0-6.5），土壤偏鹼易固定鐵離子導致根系無法吸收；建議檢測土壤酸鹼度，過鹼時可適度添加酸性泥炭土、腐植酸或低濃度硫磺資材微調。\n3. 優化水分與肥培管理：避免盆土長期積水或根系缺氧，並減少過量磷肥施用（過多磷易與鐵產生拮抗）。若兼有介殼蟲或螨類刺吸危害，請諮詢專業人員並依農業部現行核准用藥規範處理，切勿自行混藥。', '', '2026-10-13 23:08:56', NULL, 0, 'gemini_multimodal_fallback', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-diary-105', 'disease');
INSERT INTO `plant_diary` (`id`, `user_id`, `crop_id`, `status_name`, `image_url`, `disease_id`, `pest_id`, `confidence`, `suggestion`, `treatment`, `user_note`, `created_at`, `user_corrected_status`, `requires_review`, `grounding_source`, `reference_source`, `reference_url`, `reference_record_id`, `category`) VALUES (106, 2, 901, '缺鐵症', 'D:/plant_backend/static/uploads/5500a1c257ec40f09bd59c7a428909a9.jpg', 257, NULL, 0.9, '- 頂端嫩葉失綠：新葉呈現典型脈間黃化，主脈維持深綠，為鐵移動性差之生理特徵。\n- 生長受阻風險：若持續缺鐵將引發葉緣焦枯，光合作用下降並影響花芽分化。', '1. 應急葉面補鐵：以水溶性螯合鐵（EDTA-Fe，稀釋 1000-1500 倍）於清晨均勻噴施葉面，每 7-10 天一次，連續 2-3 次改善新葉失綠。\n2. 調節土壤酸鹼：介質維持微酸性（pH 6.0-6.5）。若土壤偏鹼易阻礙鐵吸收，可添加酸性泥炭土或腐植酸微調。\n3. 控水與平衡施肥：避免盆土積水爛根，並暫停高磷肥料避免拮抗；若有蟲害請依農業部核准藥劑單獨施用，勿任意混藥。', '', '2026-10-13 23:17:39', NULL, 0, 'gemini_multimodal_fallback', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-diary-106', 'disease');
INSERT INTO `plant_diary` (`id`, `user_id`, `crop_id`, `status_name`, `image_url`, `disease_id`, `pest_id`, `confidence`, `suggestion`, `treatment`, `user_note`, `created_at`, `user_corrected_status`, `requires_review`, `grounding_source`, `reference_source`, `reference_url`, `reference_record_id`, `category`) VALUES (107, 2, 932, '炭疽病', 'D:/plant_backend/static/uploads/a1fedd2b0db8462e92112d124cc30cb4.jpg', 259, NULL, 0.85, '- 葉片邊緣及葉尖呈現黃化及褐色壞疽斑塊，易導致提早落葉並削弱光合作用與植株樹勢。\n- 病原菌易於枯枝殘葉殘留，遇潮濕多雨時隨水滴飛濺擴散，增加果實感染黑斑及腐爛風險。', '1. 清除病源：剪除枯枝、病葉及落果並移出果園集中燒毀或深埋，減少炭疽病菌源殘留與傳播。\n2. 藥劑防治：發病初期輪流噴施23%亞托敏水懸劑1000倍或80%鋅錳乃浦可濕性粉劑500倍液全株防治。\n3. 樹勢管理：修剪內部過密枝條以改善通風採光，雨季前補施磷鉀肥，避免偏施氮肥以強化組織抗病力。', '', '2026-10-13 23:35:41', NULL, 0, 'gemini_multimodal_fallback', '農業部動植物防疫檢疫署病蟲害手冊', 'https://www.aphia.gov.tw', 'aphia-diary-107', 'disease');
INSERT INTO `plant_diary` (`id`, `user_id`, `crop_id`, `status_name`, `image_url`, `disease_id`, `pest_id`, `confidence`, `suggestion`, `treatment`, `user_note`, `created_at`, `user_corrected_status`, `requires_review`, `grounding_source`, `reference_source`, `reference_url`, `reference_record_id`, `category`) VALUES (108, 2, 932, '柑橘葉蟎', 'D:/plant_backend/static/uploads/65c1711ccd094c63b9cffeca56f54e0a.jpg', NULL, 236, 0.85, '- 葉片表面呈現密集失綠微斑與黃化焦枯，為柑橘葉蟎刺吸汁液所致，嚴重削弱光合作用機能。\n- 乾旱季節葉蟎繁殖迅速，若未即時壓制將引發大量落葉與果皮粗糙褐化，嚴重影響收成品質。', '1. 修剪清園：剪除樹冠內部密集枝條與嚴重褐化老葉並移出銷毀，改善通風與日照以減少蟎類孳生源。\n2. 物理防治：全株噴施99%窄域油乳劑500倍液，重點噴灑葉背以窒息成蟎與卵，避免高溫正午施用。\n3. 藥劑防治：輪替噴施20%必芬蟎水懸劑2000倍液全面防治，需確實落實安全採收期並避免抗藥性產生。', '', '2026-10-13 23:36:38', NULL, 0, 'gemini_multimodal_fallback', '農業部動植物防疫檢疫署害蟲防治指引', 'https://www.aphia.gov.tw', 'aphia-pest-diary-108', 'pest');
INSERT INTO `plant_diary` (`id`, `user_id`, `crop_id`, `status_name`, `image_url`, `disease_id`, `pest_id`, `confidence`, `suggestion`, `treatment`, `user_note`, `created_at`, `user_corrected_status`, `requires_review`, `grounding_source`, `reference_source`, `reference_url`, `reference_record_id`, `category`) VALUES (109, 2, 1022, '葉斑病', 'D:/plant_backend/static/uploads/b3c11970a59745dbace3ea525fac9998.jpg', 218, NULL, 1.0, '🌟 【主動學習自適應命中】：本影像與歷史專家覆核樣本特徵相似度達 100.0%，系統已即時採納農業專家黃金真值，精準判定為【樺木 - 葉斑病】。', '1. 請依照專家審定之對應處方進行植株管理。\n2. 維持良好通風與田間水分管理。', '', '2026-10-20 21:52:54', NULL, 0, 'visual_memory_expert_verified', '農業部樹木病蟲害診斷案例', 'https://www.google.com/search?q=birch+leaf+spot', 'aphia-樺木-葉斑病', 'disease');
